ns.QuestTexts = {
    [17] = { "Reagenzsuche in Uldaman", "Bringt zwölf Magentafunguskappen nach Thelsamar zu Ghak Heilsegen." },
    [65] = { "Die Bruderschaft der Defias", "Gryan Starkmantel möchte, dass Ihr in Seenhain mit Wiley sprecht." },
    [132] = { "Die Bruderschaft der Defias", "Bringt Wileys Nachricht nach Westfall zu Gryan Starkmantel." },
    [135] = { "Die Bruderschaft der Defias", "Bringt Wileys Nachricht nach Sturmwind zu Mathias Shaw." },
    [141] = { "Die Bruderschaft der Defias", "Bringt Shaws Bericht nach Westfall zu Gryan Starkmantel." },
    [142] = { "Die Bruderschaft der Defias", "Spürt den Boten der Defias in Westfall auf und bringt die Nachricht, die er bei sich hat, zu Starkmantel." },
    [155] = { "Die Bruderschaft der Defias", "Eskortiert den Verräter der Defias zum Geheimversteck der Defiasbruderschaft. Sobald der Verräter der Defias Euch gezeigt hat, wo sich van Cleef und seine Männer aufhalten, kehrt Ihr mit der Information zu Gryan Starkmantel zurück." },
    [166] = { "Die Bruderschaft der Defias", "Tötet Edwin van Cleef und bringt seinen Kopf zu Gryan Starkmantel." },
    [167] = { "Oh Bruder...", "Bringt Großknecht Distelklettes Abzeichen der Forscherliga nach Sturmwind zu Wilder Distelklette." },
    [168] = { "Die Suche nach Andenken", "Beschafft 4 Gewerkschaftsausweise und bringt sie nach Sturmwind zu Wilder Distelklette." },
    [214] = { "Rote Seidenkopftücher", "Späherin Riell am Turm auf der Späherkuppe möchte, dass Ihr ihr 10 rote Seidenkopftücher bringt." },
    [261] = { "Auf dem Scharlachroten Pfad", "Vernichtet 30 untote Verheerer und kehrt dann zu Bruder Anton auf die Nijelspitze zurück." },
    [275] = { "Schwärendes Land", "Tötet 8 Moorkrabbler und kehrt dann zu Rethiel dem Sumpfhüter im Sumpfland zurück." },
    [276] = { "Stapfende Pfoten", "Tötet 15 Gnolle der Moosfelle sowie 10 Bastarde der Moosfelle und kehrt dann zu Rethiel dem Sumpfhüter im Sumpfland zurück." },
    [277] = { "Feuer-Tabu", "Bringt Rethiel dem Sumpfhüter 9 kunstlose Feuersteine." },
    [303] = { "Der Dunkeleisenkrieg", "Motley Garmason in Dun Modr möchte, dass Ihr 10 Dunkeleisenzwerge, 5 Tunnelgräber der Dunkeleisenzwerge, 5 Saboteure der Dunkeleisenzwerge und 5 Demolierer der Dunkeleisenzwerge tötet." },
    [350] = { "Auf einen alten Freund verlassen", "Sprecht mit Elling Trias in Sturmwind." },
    [373] = { "Der nie verschickte Brief", "Bringt den Brief nach Sturmwind zum Stadtarchitekten Baros Alexston." },
    [377] = { "Verbrechen und Strafe", "Ratsherr Mühlenstein von Dunkelhain will, dass Ihr ihm die Hand von Dextren Ward bringt." },
    [378] = { "Tief empfundener Zorn", "Motley Garmason in Dun Modr verlangt Kam Tiefenzorns Kopf." },
    [386] = { "Verbrechen lohnt sich nicht", "Bringt Wache Berton in Seenhain den Kopf von Targorr dem Schrecklichen." },
    [387] = { "Niederschlagung des Aufstandes", "Aufseher Thelwasser aus Sturmwind will, dass Ihr im Verlies 10 Gefangene, 8 Sträflinge und 8 Aufrührer tötet." },
    [388] = { "Die Farbe von Blut", "Nikova Raskol von Sturmwind will, dass Ihr 10 rote Wollkopftücher für sie sammelt." },
    [389] = { "Bazil Thredd", "Sprecht mit Aufseher Thelwasser im Verlies." },
    [391] = { "Aufstand im Verlies", "Tötet Bazil Thredd und bringt seinen Kopf mit zurück zu Aufseher Thelwasser im Verlies." },
    [392] = { "Der seltsame Besucher", "Bringt die versiegelte Beschreibung von Thredds Besucher nach Sturmwind zu Baros Alexston." },
    [393] = { "Schatten der Vergangenheit", "Bringt die versiegelte Beschreibung von Thredds Besucher nach Sturmwind zu Meister Mathias Shaw." },
    [394] = { "Der Kopf des Ganzen", "Sprecht mit Mathias Shaw in Sturmwind." },
    [395] = { "Das Ende der Bruderschaft", "Sprecht mit Baros Alexston in Sturmwind." },
    [396] = { "Eine Audienz beim König", "Liefert Baros Alexstons Bericht über die Bruderschaft der Defias bei König Varian Wrynn in der Burg Sturmwind ab." },
    [434] = { "Der Angriff!", "Bleibt im Garten, bis Lord Gregor Lescovar und Marzon die Stille Klinge ihr Gespräch beendet haben. Schaltet sie danach beide aus, bevor Ihr nach Sturmwind zu Elling Trias zurückkehrt." },
    [463] = { "Der Sumpfhüter", "Findet den Sumpfhüter." },
    [484] = { "Häute junger Krokilisken", "Besorgt Euch 4 Häute junger Krokilisken für James Halloran im Hafen von Menethil." },
    [704] = { "Agmonds Schicksal", "Bringt Ausgrabungsleiter Eisenband am Loch Modan 4 verzierte Steinurnen." },
    [707] = { "Eisenband sucht Euch!", "Sprecht auf Eisenbands Ausgrabungsstätte am Loch Modan mit Ausgrabungsleiter Eisenband." },
    [709] = { "Lösung der Verdammnis", "Bringt Theldurin dem Verirrten die Schrifttafel von Ryun'eh." },
    [720] = { "Ein Hoffnungsschimmer", "Sucht Ausgrabungsleiter Roggendol und teilt ihm mit, dass Hammerzeh Grez noch am Leben ist." },
    [721] = { "Ein Hoffnungsschimmer", "Sucht in Uldaman nach Hammerzeh Grez." },
    [722] = { "Amulett der Geheimnisse", "Sucht Hammerzehs Amulett und bringt es ihm nach Uldaman." },
    [723] = { "Ein Funken Hoffnung", "Bringt Ausgrabungsleiter Roggendol im Ödland Hammerzehs Amulett." },
    [724] = { "Ein Funken Hoffnung", "Bringt Historiker Karnik in Eisenschmiede Hammerzehs Amulett." },
    [725] = { "Kunde über die Bedrohung breitet sich aus", "Sucht Berater Belgrum und gebt ihm die Notiz." },
    [726] = { "Kunde über die Bedrohung breitet sich aus", "Sprecht mit Historiker Karnik." },
    [727] = { "Auf nach Eisenschmiede zu 'Yagyins Zusammenstellung'", "Gebt Gerrig Knochengriff im Düsteren Viertel von Eisenschmiede das Siegelzeichen des Hammers." },
    [728] = { "Auf nach Unterstadt zu 'Yagyins Zusammenstellung'", "Bringt dem Bewahrer Bel'dugur in Unterstadt das Siegelzeichen des Hammers." },
    [735] = { "Der Stern, die Hand und das Herz", "Bringt Gerrig Knochengriff in Eisenschmiede die Gegenstände in Knochengriffs Notiz." },
    [736] = { "Der Stern, die Hand und das Herz", "Bringt dem Bewahrer Bel'dugur in Unterstadt die Gegenstände von Bel'dugurs Notiz." },
    [737] = { "Verbotenes Wissen", "Bringt Theldurin 'Yagyins Zusammenstellung'." },
    [738] = { "Sucht Agmond", "Sucht Agmond." },
    [739] = { "Murdaloc", "Tötet Agmonds Mörder Murdaloc.\n\nTötet 12 Knochenknacker der Steingrufttroggs.\n\nErstattet Ausgrabungsleiter Eisenband am Loch Modan Bericht." },
    [762] = { "Ein Botschafter des Bösen", "Tötet den Botschafter Infernus in der Festung Angor und bringt Berater Belgrum in Eisenschmiede einen Beweis, der bestätigt, dass der Botschafter tot ist." },
    [865] = { "Es muss im Horn stecken", "Erhaltet das Horn von König Schnitterklaue." },
    [870] = { "Die Vergessenen Teiche", "Sucht den Grund der Vergessenen Teiche nordwestlich des Wegekreuzes ab." },
    [877] = { "Die Brackige Oase", "Benutzt die Samenkörner, um die Risse in der Brackigen Oase zu untersuchen." },
    [880] = { "Veränderte Wesen", "Sammelt 6 Schnappkieferpanzer von den Schnappkiefern in der Brackigen Oase." },
    [914] = { "Anführer der Giftzähne", "Bringt die Edelsteine von Kobrahn, Anacondra, Pythas und Serpentis nach Donnerfels zu Nara Wildmähne." },
    [959] = { "Ärger auf den Docks", "Kranführer Moppelfuzz in Ratschet möchte, dass Ihr Zausel dem Verrückten, der sich in den Höhlen des Wehklagens versteckt, die Flasche mit 99-jährigem Portwein wieder abnehmt." },
    [962] = { "Schlangenflaum", "Die Apothekerin Zamah in Donnerfels möchte, dass Ihr zehn Schlangenflaum für sie sammelt." },
    [971] = { "Wissen in der Tiefe", "Bringt das 'Manuskript von Lorgalis' zu Schildwachenschülerin Issara zum Stützpunkt an der Grotte." },
    [1013] = { "Das Buch von Ur", "Bringt dem Bewahrer Bel'dugur im Apothekarium in Unterstadt das Buch von Ur." },
    [1014] = { "Arugal muss sterben", "Tötet Arugal und bringt Dalar Morgenweber in dem Grabmal seinen Kopf." },
    [1048] = { "In das Scharlachrote Kloster", "Tötet Hochinquisitorin Weißsträhne, den Scharlachroten Kommandant Mograine, Herod, den Scharlachroten Helden sowie den Hundemeister Loksey und meldet Euch dann wieder bei Varimathras in Unterstadt." },
    [1049] = { "Kompendium der Gefallenen", "Holt das 'Kompendium der Gefallenen' aus dem Kloster in Tirisfal und bringt es zu dem Weisen Wahrspruch in Donnerfels." },
    [1050] = { "Mythologie der Titanen", "Holt die 'Mythologie der Titanen' aus dem Kloster und bringt die der Bibliothekarin Mae Bleichstaub in Eisenschmiede." },
    [1051] = { "Vorrels Rache", "Bringt Monika Sengutz in Tarrens Mühle den Ehering von Vorrel Sengutz." },
    [1052] = { "Auf dem Scharlachroten Pfad", "Bringt Raleigh dem Andächtigen in Süderstade Bruder Antons Empfehlungsschreiben." },
    [1053] = { "Im Namen des Lichts", "Tötet Hochinquisitorin Weißsträhne, den Scharlachroten Kommandant Mograine, Herod, den Scharlachroten Helden sowie den Hundemeister Loksey und meldet Euch dann wieder bei Raleigh dem Andächtigen in Süderstade." },
    [1098] = { "Todespirscher in Burg Schattenfang", "Sucht die Todespirscher Adamant und Vincent." },
    [1100] = { "Einbraues Tagebuch", "Lest Henrig Einbraues Tagebuch." },
    [1101] = { "Die Greisin des Krals", "Bringt Falfindel Wegeshut in Thalanaar Klingenflankes Medaillon." },
    [1102] = { "Ein schreckliches Schicksal", "Bringt Auld Steinkeil in Donnerfels Klingenflankes Herz." },
    [1109] = { "Go, Go, Guano!", "Bringt dem Apothekermeister Faranell in Unterstadt 1 Häufchen Kralguano." },
    [1113] = { "Herzen des Eifers", "Apothekermeister Faranell in Unterstadt möchte 20 Herzen des Eifers." },
    [1139] = { "Die verlorene Tafel des Willens", "Sucht die Tafel des Willens und bringt sie zu Berater Belgrum in Eisenschmiede." },
    [1142] = { "Die Sterblichkeit schwindet", "Sucht und bringt Treshalas Anhänger zu Treshala Bachquell in Darnassus." },
    [1144] = { "Willix der Importeur", "Führt Willix den Importeur aus dem Kral der Klingenhauer hinaus." },
    [1149] = { "Test des Glaubens", "Wenn Ihr festen Glaubens seid, dann springt von den Planken über Tausend Nadeln." },
    [1150] = { "Test der Belastbarkeit", "Bringt Grenkas Klaue zu Dorn Ebenenpirscher in Tausend Nadeln." },
    [1151] = { "Test der Kraft", "Bringt Fragmente von Rok'Alim zu Dorn Ebenenpirscher in Tausend Nadeln." },
    [1152] = { "Test der Lehre", "Sucht Braug Dämmergeist in der Nähe des Eingangs zum Steinkrallenpfad im Steinkrallengebirge." },
    [1154] = { "Test der Lehre", "Sucht das 'Vermächtnis der Aspekte' und bringt es zu Braug Dämmergeist in der Nähe des Eingangs zum Steinkrallenpfad im Steinkrallengebirge zurück." },
    [1159] = { "Test der Lehre", "Sucht Parqual Fintallas in Unterstadt." },
    [1160] = { "Test der Lehre", "Sucht Die Anfänge der Bedrohung durch die Untoten und bringt es zu Parqual Fintallas in Unterstadt." },
    [1198] = { "Auf der Suche nach Thaelrid", "Sucht Späher Thaelrid in der Tiefschwarzen Grotte auf." },
    [1199] = { "Die Stunde der Finsternis", "Bringt 10 Zwielichtanhänger zu Schildwache Aluwyn im Stützpunkt an der Grotte." },
    [1200] = { "Schurkerei in der Tiefschwarzen Grotte", "Bringt den Kopf von Zwielichtfürst Kelris zu Ashelan Nordwald im Stützpunkt an der Grotte." },
    [1221] = { "Blaulaubknollen", "Schnappt Euch eine Kiste mit Löchern.\nSchnappt Euch einen Schnüffelnasenleitstecken.\nSchnappt Euch das Handbuch für Schnüffelnasenbesitzer und lest es.\n\nBenutzt im Kral der Klingenhauer die Kiste mit Löchern, um ein Schnüffelnasenziesel zu beschwören, und benutzt den Leitstecken bei dem Ziesel, damit es nach Knollen sucht.\n\nBringt 6 Blaulaubknollen, den Schnüffelnasenleitstecken und die Kiste mit Löchern zu Mebok Mizzyrix in Ratschet." },
    [1275] = { "Erforschung der Verderbnis", "Relwyn Schattenstern am Stützpunkt an der Grotte benötigt 8 verderbte Gehinstämme." },
    [1318] = { "Die offene Rechnung der Gordok", "Findet die Stulpen der Gordokmacht und bringt sie zu Hauptmann Krombruch in Düsterbruch.\n\nKrombruch zufolge sagen die \"Alte Zeit Geschichten\", dass Tortheldrin - ein \"gruseliger\" Elf, der sich selbst als Prinz bezeichnet- sie einem der Gordokkönige gestohlen hat." },
    [1360] = { "Wiederbeschaffte Schätze", "Holt Krom Starkarms wertvollen Besitz aus seiner Truhe in der Nördlichen Bankenhalle von Uldaman und bringt den Schatz zu ihm nach Eisenschmiede." },
    [1394] = { "Letzte Überfahrt", "Sprecht mit Dorn Ebenenpirscher in Tausend Nadeln." },
    [1424] = { "Tränenteich", "Fel'Zerul in Steinard möchte, dass Ihr 5 Artefakte der Atal'ai sammelt." },
    [1429] = { "Der Verbannte der Atal'ai", "Bringt das Artefaktbündel der Atal'ai zu dem Verbannten der Atal'ai ins Hinterland." },
    [1444] = { "Rückkehr zu Fel'Zerul", "Kehrt zu Fel'Zerul in Steinard zurück." },
    [1445] = { "Der Tempel von Atal'Hakkar", "Sammelt 20 Fetische von Hakkar und bringt sie zu Fel'Zerul in Steinard." },
    [1446] = { "Jammal'an der Prophet", "Der Verbannte der Atal'ai im Hinterland möchte den Kopf von Jammal'an." },
    [1448] = { "Auf der Suche nach dem Tempel", "Brohann Fassbauch in Sturmwind möchte, dass Ihr den Tempel von Atal'Hakkar sucht." },
    [1449] = { "Ins Hinterland", "Sprecht mit dem obersten Than, Falstad Wildhammer, am Nistgipfel im Hinterland." },
    [1450] = { "Greifenmeister Krallenaxt", "Sprecht mit Greifenmeister Krallenaxt im Horst beim Nistgipfel." },
    [1451] = { "Rhapsodie Kniegräber", "Sucht Rhapsodie Kniegräber im Hinterland." },
    [1452] = { "Rhapsodies Kalimdor-Cocktail", "Rhapsodie Kniegräber im Hinterland möchte, dass Ihr ihm 3 Muskelmägen eines Roc, 3 Groddoclebern und 3 Eisenfelllebern bringt." },
    [1469] = { "Rhapsodies Geschichte", "Bringt das Schrifttafelfragment der Atal'ai zu Brohann Fassbauch in Sturmwind." },
    [1475] = { "Im Tempel von Atal'Hakkar", "Sammelt 10 Schrifttafeln der Atal'ai für Brohann Fassbauch in Sturmwind." },
    [1486] = { "Deviatbälge", "Nalpak in den Höhlen des Wehklagens möchte 20 Deviatbälge." },
    [1487] = { "Ausrottung der Deviat", "Ebru in den Höhlen des Wehklagens möchte, dass Ihr 7 Deviatverheerer, 7 Deviatvipern, 7 Deviatschlurfer und 7 Deviatschreckensfange tötet." },
    [1489] = { "Hamuul Runentotem", "Sprecht mit Hamuul Runentotem." },
    [1490] = { "Nara Wildmähne", "Sprecht mit Nara Wildmähne." },
    [1491] = { "Klugheitstränke", "Sammelt 6 Portionen Klageessenz." },
    [1649] = { "Der Foliant der Tapferkeit", "Sprecht mit Duthorian Rall in Sturmwind." },
    [1650] = { "Der Foliant der Tapferkeit", "Sucht Daphne Stillbrunn in Westfall." },
    [1651] = { "Der Foliant der Tapferkeit", "Verteidigt Daphne Stillbrunn vor dem Angriff der Defias.\n\nKeiner Eurer Geister darf aus seinen irdischen Fesseln befreit werden, wenn Ihr erfolgreich sein wollt.\n\nSprecht erneut mit Daphne Stillbrunn, wenn Ihr erfolgreich wart." },
    [1652] = { "Der Foliant der Tapferkeit", "Sprecht mit Duthorian Rall in Sturmwind." },
    [1653] = { "Die Prüfung der Rechtschaffenheit", "Sprecht mit Jordan Stillbrunn in Eisenschmiede." },
    [1654] = { "Die Prüfung der Rechtschaffenheit", "Sucht mit Jordans Waffennotizen etwas Weißsteineichenholz, Bailors aufbereitete Erzlieferung, Jordans Schmiedehammer und einen Koredelstein und bringt alles zusammen zu Jordan Stillbrunn in Eisenschmiede." },
    [1740] = { "Die Kugel von Soran'ruk", "Sucht 3 Fragmente von Soran'ruk und 1 großes Fragment von Soran'ruk und bringt sie zu Doan Karhan im Brachland." },
    [1806] = { "Die Prüfung der Rechtschaffenheit", "Wartet, bis Jordan Stillbrunn eine Waffe für Euch geschmiedet hat." },
    [1947] = { "Reise in die Marschen", "Sprecht mit Tabetha." },
    [1949] = { "Verborgene Geheimnisse", "Sprecht mit Magus Tirth in der Schimmernden Ebene." },
    [1950] = { "Der Knüller schlechthin", "Bringt den Satz für Tirths Geldkassette in Erfahrung und kehrt zu Tirth zurück." },
    [1951] = { "Rituale der Macht", "Bringt das Buch 'Rituale der Macht' zu Tabetha in den Düstermarschen." },
    [1952] = { "Der Zauberstab des Magiers", "Sprecht nach ihrem Ritual mit Tabetha." },
    [1953] = { "Rückkehr in die Marschen", "Sprecht mit Tabetha." },
    [1954] = { "Die Höllenkugel", "Bringt eine Höllenkugel zu Tabetha in den Düstermarschen." },
    [1955] = { "Die Austreibung", "Tötet den Dämon der Kugel und sprecht dann mit Tabetha." },
    [1956] = { "Kraft in Uldaman", "Beschafft Euch eine Obsidiankraftquelle und bringt sie in die Düstermarschen zu Tabetha." },
    [1957] = { "Manawogen", "Vernichtet 12 Manawogen innerhalb des Zeitlimits." },
    [1958] = { "Himmlische Macht" },
    [2040] = { "Unterirdischer Angriff", "Holt das Gnoamsprenkelspross aus den Todesminen und bringt es Shoni der Schtillen in Sturmwind." },
    [2198] = { "Die zerrissene Halskette", "Sucht nach dem Erschaffer der zerrissenen Halskette, um etwas über ihren möglichen Wert zu erfahren." },
    [2199] = { "Lehren haben ihren Preis", "Bringt fünf Silberbarren zu Talvash del Kissel in Eisenschmiede." },
    [2200] = { "Rückkehr nach Uldaman", "Sucht in Uldaman nach Hinweisen auf den momentanen Zustand von Talvashs Halskette. Der getötete Paladin, den Talvash erwähnte, hatte die Kette zuletzt." },
    [2201] = { "Suche nach den Edelsteinen", "Findet den Rubin, den Saphir und den Topas, die in ganz Uldaman verstreut sind. Wenn Ihr sie habt, wendet Euch aus der Ferne an Talvash del Kissel, indem Ihr die Wahrsagephiole nutzt, die er Euch zuvor gegeben hat.\n\nAus dem Tagebuch, wisst Ihr...\n* Der Rubin wurde in einer Bastion der Zwerge der Schattenschmiede versteckt.\n* Der Topas steckt in einer Urne in einem der Trogggebiete, in der Nähe einiger Zwerge der Allianz.\n\n* Der Saphir wurde von Grimlok, dem Anführer der Troggs, mitgenommen." },
    [2202] = { "Reagenzsuche in Uldaman", "Bringt 12 Magentafunguskappen nach Kargath zu Jarkal Moosblut." },
    [2203] = { "Reagenziensuche im Ödland II", "Benutzt die leeren thaumaturgischen Gefäße bei versengten Wächtergroßdrachen im Ödland. Wenn Ihr sie gefüllt habt, bringt sie zu Jarkal Moosblut in Kargath." },
    [2204] = { "Restaurierung der Halskette", "Besorgt Euch eine Kraftquelle vom mächtigsten Konstrukt, das Ihr in Uldaman finden könnt, und liefert sie bei Talvash del Kissel in Eisenschmiede ab." },
    [2240] = { "Die geheime Kammer", "Lest Baelogs Tagebuch, erforscht die geheime Kammer und erstattet dann Ausgrabungsleiter Sturmlanze Bericht." },
    [2258] = { "Reagenziensuche im Ödland", "Bringt Jarkal Moosblut in Kargath im Ödland 5 Bussardmuskelmägen, 10 Klippenkojotenfangzähne und 5 Felselementarsplitter." },
    [2278] = { "Die Platinscheiben", "Sprecht mit dem Steinbehüter und findet heraus, welche uralten Lehren er aufbewahrt. Sobald Ihr alles erfahren habt, was er weiß, aktiviert die Scheiben von Norgannon." },
    [2279] = { "Die Platinscheiben", "Bringt die Miniaturausgabe der Scheiben von Norgannon zur Forscherliga nach Eisenschmiede." },
    [2280] = { "Die Platinscheiben", "Bringt die Miniaturausgabe der Scheiben von Norgannon zu jemandem, der sich brennend dafür interessiert." },
    [2283] = { "Wiederbeschaffung der Halskette", "Sucht in der Grabungsstätte von Uldaman nach einer wertvollen Halskette und bringt sie nach Orgrimmar zu Dran Droffers. Die Halskette ist vielleicht beschädigt." },
    [2284] = { "Wiederbeschaffung der Halskette, Teil 2", "Sucht in den Tiefen von Uldaman nach einem Hinweis auf den Verbleib der Edelsteine." },
    [2318] = { "Übersetzung des Tagebuchs", "Sucht jemanden, der das Tagebuch des Paladins übersetzen kann. Der nächstgelegene Ort, wo Ihr so jemanden finden könntet, ist Kargath im Ödland." },
    [2338] = { "Übersetzung des Tagebuchs", "Leiht Jarkal die Halskette. Im Gegenzug wird er das Tagebuch für Euch übersetzen." },
    [2339] = { "Findet die Edelsteine und die Kraftquelle", "Beschafft in Uldaman alle drei Edelsteine sowie eine Kraftquelle für die Halskette und bringt sie anschließend zu Jarkal Moosblut nach Kargath. Jarkal glaubt, dass sich eine Kraftquelle vielleicht im stärksten Konstrukt in Uldaman findet.\n\nAus dem Tagebuch, wisst Ihr...\n* Der Rubin wurde in einer Bastion der Zwerge der Schattenschmiede versteckt.\n* Der Topas steckt in einer Urne in einem der Trogggebiete, in der Nähe einiger Zwerge der Allianz.\n* Der Saphir wurde von Grimlok, dem Anführer der Troggs, mitgenommen." },
    [2340] = { "Ablieferung der Edelsteine", "Liefert die Halskette und die geborgenen Edelsteine bei Dran Droffers in Orgrimmar ab." },
    [2341] = { "Wiederbeschaffung der Halskette, Teil 3", "Besucht Jarkal Moosblut in Kargath, um festzustellen, ob er Erfolg gehabt hat." },
    [2342] = { "Wiederbeschaffte Schätze", "Holt Patrick Garretts Familienschatz aus der Truhe der Familie in der Südlichen Bankenhalle von Uldaman und bringt diesen zu ihm nach Unterstadt." },
    [2361] = { "Restaurierung der Halskette" },
    [2398] = { "Die verschollenen Zwerge", "Sucht in Uldaman nach Baelog." },
    [2418] = { "Kraftsteine", "Bringt Riggelfuzz im Ödland 8 Kraftsteine aus Dentrium und 8 Kraftsteine aus An'Alleum." },
    [2439] = { "Die Platinscheiben", "Bringt Euren Belohnungsgutschein zu Dinita Zasterstein im Tresor von Eisenschmiede." },
    [2440] = { "Die Platinscheiben", "Bringt den Belohnungsgutschein zu Bena Winterhuf nach Donnerfels." },
    [2500] = { "Reagenziensuche im Ödland", "Beschafft die Reagenzien, die Ghak Heilsegen aus dem Ödland braucht, und bringt sie ihm nach Thelsamar." },
    [2501] = { "Reagenziensuche im Ödland II", "Benutzt die leeren thaumaturgischen Gefäße bei versengten Wächtergroßdrachen im Ödland. Wenn Ihr sie gefüllt habt, bringt sie zu Ghak Heilsegen in Thelsamar." },
    [2745] = { "Eindringen ins Schloss", "Sprecht in Schloss Sturmwind mit Tyrion." },
    [2746] = { "Nicht unwichtige Gegenstände", "Bringt 3 Stück Seidenstoff und 2 frische Äpfel von Clara nach Sturmwind zu Tyrion." },
    [2768] = { "Wünschel-mato-Rute", "Bringt die Wünschel-mato-Rute nach Gadgetzan zu Chefingenieur Bilgenritzel." },
    [2770] = { "Gahz'rilla", "Bringt Wizzel Kupferbolz in der Schimmernden Ebene Gahz'rillas energiegeladene Schuppe." },
    [2841] = { "Maschinenkriege", "Besorgt die Maschinenblaupausen und Thermadrahts Safekombination aus Gnomeregan und bringt sie zu Nogg nach Orgrimmar." },
    [2842] = { "Chefingenieur Scooty", "Sprecht mit Scooty in Beutebucht." },
    [2843] = { "Gnomer-weeeeg!", "Wartet, bis Scooty den Goblintransponder kalibriert hat." },
    [2846] = { "Tiara der Tiefen", "Bringt die Tiara der Tiefen zu Tabetha in den Düstermarschen." },
    [2865] = { "Skarabäuspanzerschalen", "Bringt Tran'rek in Gadgetzan 5 unbeschädigte Skarabäuspanzerschalen." },
    [2904] = { "Eine schöne Bescherung", "Begleitet Kernobee zur Uhrwerkgasse und meldet Euch dann wieder bei Scooty in Beutebucht." },
    [2922] = { "Rettet Techbots Hirn!", "Bringt Techbots Speicherkern zu Tüftlermeister Oberfunks nach Eisenschmiede." },
    [2924] = { "Grundlegende Artifixe", "Bringt Klockmort Spannsplint in Eisenschmiede 12 grundlegende Artifixe." },
    [2926] = { "Gnogaine", "Sammelt mit der leeren bleiernen Sammelphiole radioaktive Ablagerungen bestrahlter Eindringlinge oder Plünderer. Sobald sie voll ist, bringt Ihr sie zu Ozzie Wechselvolt nach Kharanos zurück." },
    [2928] = { "Gyrobohrmatische Exkavation", "Bringt 24 robomechanische Innereien zu Shoni nach Sturmwind." },
    [2929] = { "Der große Verrat", "Reist nach Gnomeregan und tötet Robogenieur Thermadraht. Kehrt zu Hochtüftler Mekkadrill zurück, wenn der Auftrag ausgeführt ist." },
    [2930] = { "Datenrettung", "Bringt Mechanikermeister Gussmuff in Eisenschmiede eine Prismalochkarte." },
    [2933] = { "Giftflaschen", "Bringt eine Giftflasche zu einem Apotheker nach Tarrens Mühle." },
    [2934] = { "Unbeschädigter Giftbeutel", "Bringt Apotheker Lydon in Tarrens Mühle einen unbeschädigten Giftbeutel." },
    [2935] = { "Konsultiert Meister Gadrin", "Sprecht mit Meister Gadrin in Sen'jin." },
    [2936] = { "Der Spinnengott", "Lest von der Schrifttafel des Theka, um den Namen des Spinnengottes der Bleichborken zu erfahren, und kehrt dann zu Meister Gadrin zurück." },
    [2937] = { "Die Beschwörung von Shadra", "Besiegt Shadra am Altar von Shadra'Alor und bringt ihr Gift zu Apotheker Lydon nach Tarrens Mühle." },
    [2938] = { "Gift für Unterstadt", "Bringt Faranells Päckchen zu Apothekermeister Faranell nach Unterstadt." },
    [2945] = { "Schmutzverkrusteter Ring", "Findet einen Weg, den schmutzverkrusteten Ring zu säubern." },
    [2946] = { "Mal sehen, was passiert...", "Bringt die Miniaturplatinscheiben zu den Toren von Uldum in Tanaris und sucht nach Hinweisen auf die Verbindung zwischen beidem." },
    [2947] = { "Die Rückkehr des Rings", "Ihr könnt den Ring entweder behalten oder die Person finden, die für die Prägung und Gravuren auf der Innenseite des Rings verantwortlich ist." },
    [2948] = { "Gnomenverbesserungen", "Bringt Talvash del Kissel in Eisenschmiede den glänzenden Goldring, einen Silberbarren, einen Moosachat und 30 Silbermünzen." },
    [2949] = { "Die Rückkehr des Rings", "Ihr könnt den Ring entweder behalten oder die Person finden, die für die Prägung und Gravuren auf der Innenseite des Rings verantwortlich ist." },
    [2950] = { "Noggs Ringerneuerung", "Bringt Nogg in Orgrimmar den glänzenden Goldring, einen Silberbarren, einen Moosachat und 30 Silbermünzen." },
    [2951] = { "Der Funkelmat 5200!", "Gebt einen schmutzverkrusteten Gegenstand in den Funkelmat 5200 und stellt sicher, dass Ihr drei Silbermünzen habt, um die Maschine zu aktivieren." },
    [2952] = { "Der Funkelmat 5200!" },
    [2953] = { "Funkelmatastisch" },
    [2954] = { "Der Steinbehüter", "Findet den Zweck des Steinbehüters von Norgannon heraus und interagiert dann mit dem Podest von Uldum in der Tanariswüste." },
    [2962] = { "Das einzige Heilmittel ist mehr grünes Leuchten", "Reist nach Gnomeregan und bringt etwas von der hoch konzentrierten radioaktiven Ablagerung zurück. Seid gewarnt, die Ablagerung ist instabil und wird ziemlich schnell zerfallen.\n\nOzzie wird außerdem Eure schwere bleierne Phiole benötigen, nachdem die Aufgabe erledigt ist." },
    [2963] = { "Omen von Uldum", "Sprecht mit Historiker Karnik in der Halle der Forscher in Eisenschmiede." },
    [2964] = { "Eine zukünftige Aufgabe", "Sprecht mit Hochforscher Magellas in Eisenschmiede." },
    [2965] = { "Omen von Uldum", "Sprecht mit Nara Wildmähne auf der Anhöhe der Ältesten in Donnerfels." },
    [2966] = { "Mal sehen, was passiert...", "Bringt die Miniaturplatinscheiben zu den Toren von Uldum in Tanaris und sucht nach Hinweisen auf die Verbindung zwischen beidem." },
    [2967] = { "Rückkehr nach Donnerfels", "Sprecht mit Nara Wildmähne in Donnerfels." },
    [2968] = { "Eine zukünftige Aufgabe", "Sprecht mit dem Weisen Wahrspruch in Donnerfels." },
    [2977] = { "Rückkehr nach Eisenschmiede", "Sprecht mit Historiker Karnik in Eisenschmiede." },
    [2988] = { "Käfige der Bleichborken", "Durchsucht die Käfige in den beiden Dörfern der Bleichborken und kehrt dann zu Greifenmeister Krallenaxt zurück." },
    [2989] = { "Der Altar von Zul", "Überprüft die Oberfläche des Altars von Zul und kehrt dann zu Greifenmeister Krallenaxt zurück." },
    [2990] = { "Thadius Grimmschatten", "Bringt Scharfschnabels Feder zu Thadius Grimmschatten in die Verwüsteten Lande." },
    [2991] = { "Nekrums Medaillon", "Bringt Thadius Grimmschatten in den Verwüsteten Landen Nekrums Medaillon." },
    [2992] = { "Die Weissagung", "Wartet, bis Grimmschatten das Rutengangritual durchgeführt hat." },
    [2993] = { "Rückkehr ins Hinterland", "Sprecht mit Greifenmeister Krallenaxt." },
    [2994] = { "Scharfschnabels Rettung", "Kämpft Euch bis zum Gipfel von Jintha'Alor durch, tötet die üble Priesterin Hexx, um an den Schlüssel zu Scharfschnabels Käfig zu kommen, und rettet Scharfschnabel." },
    [3042] = { "Trollaushärter", "Bringt 20 Phiolen Trollaushärter zu Trenton Lichthammer in Gadgetzan." },
    [3341] = { "Das Ende bringen", "Andrew Braunell will, dass Ihr Amnennar den Kältebringer tötet und ihm dessen Schädel bringt." },
    [3369] = { "Alptraum", "Bringt den Alptraumsplitter zu Hamuul Runentotem auf der Anhöhe der Ältesten." },
    [3370] = { "Alptraum", "Bringt den Alptraumsplitter zu Mathrengyl Bärenfährte in Darnassus." },
    [3373] = { "Die Essenz des Eranikus", "Legt die Essenz von Eranikus in den Essenzborn, der sich in dem Versunkenen Tempel in seinem Unterschlupf befindet." },
    [3374] = { "Die Essenz des Eranikus", "Bringt den Schwurstein von Yseras Drachenschwarm sowie die gebundene Essenz des Eranikus zu Itharius in die Sümpfe des Elends. Dort werdet Ihr Eure Entscheidung treffen, ob Ihr Yseras Drachenschwarm helfen wollt oder nicht." },
    [3375] = { "Ersatzphiole", "Bringt einen Manatrank, Kohle und Süßen Nektar zu Talvash del Kissel in Eisenschmiede, um einen Ersatz für Talvashs Wahrsagephiole zu bekommen." },
    [3380] = { "Der Versunkene Tempel", "Sucht Marvon Nietensucher in Tanaris." },
    [3441] = { "Göttliche Vergeltung", "Lasst Kalaran Windklinge seine Geschichte erzählen." },
    [3442] = { "Die fehlerlose Flamme", "Sammelt 4 Herzen der Flamme und 4 Kugeln Golemöl und bringt die Gegenstände zu Kalaran Windklinge." },
    [3443] = { "Das Schmieden des Schafts", "Bringt 8 mit Thorium beschichtete Dolche zu Kalaran Windklinge." },
    [3444] = { "Der runde Stein", "Holt den runden Stein aus Marvon Nietensuchers Werkstatt in Ratschet." },
    [3445] = { "Der Versunkene Tempel", "Sucht Marvon Nietensucher in Tanaris." },
    [3446] = { "In die Tiefen", "Sucht den Altar von Hakkar im Versunkenen Tempel in den Sümpfen des Elends." },
    [3447] = { "Das Geheimnis des Kreises", "Reist zum Versunkenen Tempel und enthüllt das Geheimnis, das sich in dem Kreis der Statuen verbirgt." },
    [3452] = { "Die Ummantelung der Flamme", "Bringt ein Symbol von Ragnaros zu Kalaran Windklinge." },
    [3453] = { "Die Fackel der Vergeltung", "Wartet bis Kalaran Windklinge die Fackel der Vergeltung vollendet hat." },
    [3454] = { "Die Fackel der Vergeltung", "Nehmt die Fackel der Vergeltung." },
    [3462] = { "Knappe Malzdarr", "Sprecht mit dem Knappen Malzdarr." },
    [3463] = { "Setzt sie in Brand!", "Steckt die Wachpostentürme im Norden, Süden, Osten und Westen in Brand, indem Ihr die Fackel der Vergeltung innerhalb der einzelnen Gebäude benutzt." },
    [3481] = { "Plunder...", "Öffnet die Truhe." },
    [3512] = { "Mit Eranikus' eigenen Worten", "Reist in den östlichen Teil von Winterquell und sprecht mit Umbranse, dem Geistsprecher." },
    [3520] = { "Kreischergeister", "Fangt die Geister von 3 Kreischern in Feralas ein und kehrt dann zu Yeh'kinya beim Dampfdruckpier zurück." },
    [3523] = { "Geißel der Hügel", "Wenn Ihr Belnistrasz helfen wollt, sprecht noch einmal mit ihm und übergebt ihm den Schwurstein, den er Euch gab." },
    [3525] = { "Ausschalten des Götzen", "Begleitet Belnistrasz zum Götzen der Stacheleber in den Hügeln der Klingenhauer.\n\nBeschützt Belnistrasz, während er das Ritual durchführt, um den Götzen auszuschalten." },
    [3527] = { "Die Prophezeiung von Mosh'aru", "Bringt die erste und die zweite Schrifttafel von Mosh'aru zu Yeh'kinya nach Tanaris." },
    [3528] = { "Der Gott Hakkar", "Bringt das gefüllte Ei von Hakkar zu Yeh'kinya nach Tanaris." },
    [3636] = { "Das Licht bringen", "Erzbischof Benedictus will, dass Ihr Amnennar den Kältebringer in den Hügeln der Klingenhauer tötet." },
    [3701] = { "Die glimmenden Ruinen von Thaurissan", "Begebt Euch zu den Ruinen von Thaurissan in der Brennenden Steppe und sammelt Informationen über die Relikte von Thaurissan. Kehrt zur königlichen Historikerin Archesonus zurück, wenn Ihr die Informationen besorgt habt." },
    [3702] = { "Die glimmenden Ruinen von Thaurissan", "Hört die Erzählung der königlichen Historikerin Archesonus über die Geschichte von Thaurissan." },
    [3765] = { "Verderbnis in der Fremde", "Reist zu Gershala Nachtraunen in Auberdine." },
    [3801] = { "Dunkeleisenerbe", "Sprecht mit Franclorn Schmiedevater bei Schmiedevaters Grabmal im Schwarzfels, wenn Ihr daran interessiert seid, einen Schlüssel für die Hauptstadt zu erhalten." },
    [3802] = { "Dunkeleisenerbe", "Erschlagt Fineous Dunkelader und bergt den großen Hammer Eisenhölle. Bringt Eisenhölle zum Schrein von Thaurissan und legt ihn auf die Statue von Franclorn Schmiedevater." },
    [3906] = { "Disharmonie der Flamme", "Reist zum Steinbruch im Schwarzfels und tötet Übermeister Pyron. Kehrt zu Donnerherz zurück, sobald Ihr den Auftrag erledigt habt." },
    [3907] = { "Disharmonie des Feuers", "Betretet die Schwarzfelstiefen und spürt Lord Incendius auf. Tötet ihn und bringt jegliche Informationsquelle, die Ihr finden könnt, zu Donnerherz." },
    [3981] = { "Kommandant Gor'shak", "Sucht Kommandant Gor'shak in den Schwarzfelstiefen.\n\nIhr erinnert Euch, dass auf dem primitiv gezeichneten Bild des Orcs auch Gitter vor dem Gesicht zu sehen waren. Vielleicht solltet Ihr nach einer Art Gefängnis suchen." },
    [3982] = { "Was ist los?", "Verteidigt Gor'shak." },
    [4001] = { "Was ist los?", "Sprecht mit Kharan Hammermacht und sammelt Informationen über die Entführung von Prinzessin Moira Bronzebart. Bringt diese Informationen dann zu Thrall nach Orgrimmar.\n\nIhr erinnert Euch, dass Gor'shak gesagt hat, Kharan werde in einer Zelle in seiner Nähe festgehalten." },
    [4002] = { "Die Östlichen Königreiche", "Sprecht mit Thrall, wenn Ihr bereit seid, die von ihm geplante Mission zu übernehmen." },
    [4003] = { "Die königliche Rettung", "Tötet Imperator Dagran Thaurissan und befreit Prinzessin Moira Bronzebart von seinem bösen Zauber." },
    [4004] = { "Ist die Prinzessin gerettet?", "Kehrt zu Thrall in der Feste Grommash in Orgrimmar zurück." },
    [4022] = { "Eine Kostprobe der Flamme", "Zeigt Cyrus Therepentous die abgestreifte Haut des schwarzen Drachenschwarms, die Ihr von Kalaran Windklinge erhalten habt." },
    [4023] = { "Eine Kostprobe der Flamme", "Zeigt Cyrus Therepentous einen Beweis für Eure Nützlichkeit.\n\nIhr habt so ein Gefühl, dass Cyrus bereits weiß, dass Ihr unwürdig seid." },
    [4024] = { "Eine Kostprobe der Flamme", "Begebt Euch in die Schwarzfelstiefen und tötet Bael'Gar.\n\nIhr wisst lediglich, dass der Riese irgendwo in den Schwarzfelstiefen haust. Vergesst nicht, die veränderte Haut des schwarzen Drachenschwarms mit Bael'Gars Überresten zu benutzen und damit die feurige Essenz einzufangen.\n\nBringt die eingeschlossene feurige Essenz zu Cyrus Therepentous zurück." },
    [4061] = { "Aufstieg der Maschinen", "Begebt Euch in die Brennende Steppe und beschafft für Theodora Mulvadania 10 gerissene Elementarsplitter.\n\nEuch fällt ein, dass Theodora gesagt hat, die Golems und Elementare in der Gegend seien eine gute Quelle für solche Splitter." },
    [4062] = { "Aufstieg der Maschinen", "Bringt die Elementarsplitterprobe zu Lotwil Veriatus.\n\nIhr erinnert Euch, dass Theodora sagte, Lotwil sei in einem Lager im Osten stationiert." },
    [4063] = { "Aufstieg der Maschinen", "Sucht und tötet Golemlord Argelmach. Bringt Lotwil seinen Kopf. Außerdem müsst Ihr 10 intakte Elementarkerne von den Wuthäschergolems und Kriegshetzerkonstrukten, die Argelmach beschützen, beschaffen. Das wisst Ihr, weil Ihr übernatürliche Fähigkeiten habt." },
    [4081] = { "SOFORT TÖTEN: Dunkeleisenzwerge", "Begebt Euch in die Schwarzfelstiefen und vernichtet die üblen Aggressoren!\n\nKriegsherr Bluthauer möchte, dass Ihr 15 Gardisten der Zorneshämmer, 10 Aufseher der Zorneshämmer und 5 Fußsoldaten der Zorneshämmer tötet. Kehrt zu ihm zurück, sobald Ihr die Aufgabe erfüllt habt." },
    [4082] = { "SOFORT TÖTEN: Hochrangige Führungskräfte der Dunkeleisenzwerge", "Begebt Euch in die Schwarzfelstiefen und vernichtet die üblen Aggressoren!\n\nKriegsherr Bluthauer möchte, dass Ihr 10 Sanitäter der Zorneshämmer, 10 Soldaten der Zorneshämmer und 10 Offiziere der Zorneshämmer tötet. Kehrt zu ihm zurück, sobald Ihr die Aufgabe erfüllt habt." },
    [4121] = { "Gefährliche Zwickmühle", "Eskortiert Euren Gefangenen, Grark Lorkrub, durch die Brennende Steppe und durch den Schwarzfels in die Sengende Schlucht.\n\nEuch fällt ein, dass Lexlort gesagt hat, seine Männer würden auf der anderen Seite warten, um Grark in Gewahrsam zu nehmen.\n\nIhr werdet außerdem Eure Thoriumfesseln an Lexlort übergeben müssen." },
    [4122] = { "Grark Lorkrub", "Begebt Euch in die Brennende Steppe und sucht Grark Lorkrub. Ihr erinnert Euch, dass Lexlort gesagt hat, er sei zuletzt in einer großen Festung des Schwarzfelsklans gesehen worden.\n\nWenn Ihr Grark Lorkrub gefunden habt, verwendet die Thoriumfesseln, um ihn zu binden, und bringt ihn dann über den Schwarzfels in die Sengende Schlucht zurück. Lexlorts Männer werden auf der anderen Seite warten, um Grark in Gewahrsam zu nehmen." },
    [4123] = { "Das Herz des Berges", "Bringt das 'Herz des Berges' zu Maxwort Funkelglanz in der Brennenden Steppe." },
    [4126] = { "Hurley Pestatem", "Bringt Ragnar Donnerbräu in Kharanos das gestohlene Donnerbräurezept." },
    [4132] = { "Operation: Tod dem Zornesschmied", "Begebt Euch zu den Schwarzfelstiefen und eliminiert General Zornesschmied! Kehrt zum Kriegsherrn Bluthauer zurück, sobald Ihr diese Aufgabe erledigt habt." },
    [4134] = { "Verlorenes Donnerbräurezept", "Bringt Vivian Lagrave in Kargath das gestohlene Donnerbräurezept." },
    [4136] = { "Ribbly Schraubstutz", "Bringt Yuka Schraubstutz in der Brennenden Steppe Ribblys Kopf." },
    [4141] = { "Muigin und Larion", "Sammelt 15 Blutblüten und kehrt zu Muigin zurück." },
    [4142] = { "Ein Besuch bei Gregan", "Bringt Gregan Hopfenspei in Feralas eine Blutblüte." },
    [4143] = { "Der Dunst des Bösen", "Sammelt 5 Proben Dunst der Atal'ai und bringt sie Muigin im Krater von Un'Goro." },
    [4144] = { "Blutblütensprösslinge" },
    [4145] = { "Larion und Muigin", "Jagt 5 Blutblütenpeitscher, 5 Blutblütendrescher, 5 Blutblütenschinder und 5 Blutblütenfallen für Larion in Marschalls Zuflucht." },
    [4146] = { "Treibstoff für die Unkrautvernichtung", "Bringt Larion in Marschalls Zuflucht den ungeladenen Unkrautvernichter und 5 Proben Dunst der Atal'ai." },
    [4147] = { "Marvons Werkstatt", "Reist zu Marvon Nietensuchers Werkstatt in Ratschet." },
    [4148] = { "Blutblütenvernichter" },
    [4182] = { "Drachkin-Bedrohung", "Erschlagt 15 schwarze Brutlinge, 10 Exemplare der schwarzen Großdrachenbrut, 4 schwarze Wyrmkin und 1 Schwarzdrachen." },
    [4183] = { "Die wahren Meister", "Reist nach Seenhain im Rotkammgebirge und händigt Magistrat Solomon Helendis Flusshorns Brief aus." },
    [4184] = { "Die wahren Meister", "Reist nach Sturmwind und tragt Solomons Hilfegesuch dem König Varian Wrynn vor.\n\nDer König residiert in Burg Sturmwind." },
    [4185] = { "Die wahren Meister", "Sprecht zuerst mit Lady Katrana Prestor, dann mit Hochlord Bolvar Fordragon." },
    [4186] = { "Die wahren Meister", "Händigt Wrynns Erlass an Magistrat Solomon in Seenhain aus." },
    [4201] = { "Der Liebestrank", "Bringt 4 Gromsblut-Kräuter, 10 Riesensilbervenen und Nagmaras gefüllte Phiole zu Herrin Nagmara in den Schwarzfelstiefen." },
    [4223] = { "Die wahren Meister", "Sprecht mit Marschall Maxwell in der Brennenden Steppe." },
    [4224] = { "Die wahren Meister", "Sprecht mit dem struppigen John." },
    [4241] = { "Marschall Windsor", "Reist zum Schwarzfels im Nordwesten und dann weiter zu den Schwarzfelstiefen. Findet heraus, was aus Marschall Windsor geworden ist.\n\nIhr erinnert Euch daran, dass der struppige John sagte, man hätte Windsor in ein Gefängnis verschleppt." },
    [4242] = { "Verlorene Hoffnung", "Überbringt Marschall Maxwell bei Morgans Wacht in der Brennenden Steppe die schlechten Neuigkeiten." },
    [4262] = { "Übermeister Pyron", "Erschlagt Übermeister Pyron.\n\nIhr erinnert Euch an Jalindas Worte, dass Pyron den Steinbruch bewachen würde. Vielleicht solltet Ihr dort nachsehen?" },
    [4263] = { "Incendius!", "Sucht Lord Incendius in den Schwarzfelstiefen und vernichtet ihn!" },
    [4264] = { "Eine zusammengeknüllte Notiz", "Soeben seid Ihr auf etwas gestoßen, das Marschall Windsor mit Sicherheit sehr interessiert. Vielleicht besteht ja doch noch Hoffnung." },
    [4282] = { "Ein Funken Hoffnung", "Holt Marschall Windsors verloren gegangene Informationen zurück.\n\nMarschall Windsor glaubt, dass sich die Informationen in den Händen des Golemlords Argelmach und des Generals Zornesschmied befinden." },
    [4286] = { "Das gute Zeug", "Beschafft Euch 20 Dunkeleisengürteltaschen." },
    [4322] = { "Gefängnisausbruch!", "Helft Marschall Windsor, seine Ausrüstung zurückzuholen und seine Freunde zu befreien. Kehrt zu Marschall Maxwell zurück, wenn Ihr Erfolg hattet." },
    [4341] = { "Kharan Hammermacht", "Begebt Euch in die Schwarzfelstiefen und findet Kharan Hammermacht.\n\nDer König erwähnte, dass Kharan dort gefangen sei - vielleicht solltet Ihr nach einem Gefängnis Ausschau halten." },
    [4342] = { "Kharans Geschichte", "Lasst Kharan Hammermacht seine Geschichte erzählen." },
    [4361] = { "Der Überbringer schlechter Botschaften...", "Kehrt nach Eisenschmiede zurück und überbringt König Magni Bronzebart die schlechten Nachrichten." },
    [4362] = { "Das Schicksal des Königreichs", "Kehrt in die Schwarzfelstiefen zurück und rettet Prinzessin Moira Bronzebart aus den Fängen des bösen Imperators Dagran Thaurissan." },
    [4363] = { "Die Überraschung der Prinzessin", "Kehrt nach Eisenschmiede zurück und sprecht mit König Magni Bronzebart." },
    [4601] = { "Der Funkelmat 5200!", "Gebt einen schmutzverkrusteten Gegenstand in den Funkelmat 5200 und stellt sicher, dass Ihr drei Silbermünzen habt, um die Maschine zu aktivieren." },
    [4602] = { "Der Funkelmat 5200!", "Gebt einen schmutzverkrusteten Gegenstand in den Funkelmat 5200 und stellt sicher, dass Ihr drei Silbermünzen habt, um die Maschine zu aktivieren." },
    [4603] = { "Funkelmatastisch" },
    [4604] = { "Funkelmatastisch" },
    [4605] = { "Der Funkelmat 5200!" },
    [4606] = { "Der Funkelmat 5200!" },
    [4701] = { "Stellt sie ab", "Begebt Euch zur Schwarzfelsspitze und vernichtet die Quelle der Bedrohung durch die Worgs. Als Ihr Helendis verlasst, ruft er Euch noch einen Namen hinterher: Halycon. Darauf beziehen sich die Orcs im Zusammenhang mit den Worgs." },
    [4724] = { "Die Herrin der Meute", "Erschlagt Halycon, die Rudelführerin der Worgs der Blutäxte." },
    [4726] = { "Brutlingessenz", "Bringt 8 Brutlingessenzen sowie den Draco-Incarcinatrix 900 zu Tinkee Kesseldampf auf dem Flammenkamm in der Brennenden Steppe." },
    [4729] = { "Kiblers Exotische Tiere", "Begebt Euch zur Schwarzfelsspitze und sucht Worgwelpen der Blutäxte. Benutzt den Käfig, um die wilden kleinen Bestien zu transportieren. Bringt einen eingesperrten Worgwelpen zu Kibler." },
    [4734] = { "Ei-Frosten", "Benutzt den Prototyp des Eiszilloskops an einem Ei im Horst der Schwarzfelsspitze." },
    [4735] = { "Eiersammlung", "Bringt 8 eingesammelte Dracheneier sowie das kollektronische Modul zu Tinkee Kesseldampf auf dem Flammenkamm in der Brennenden Steppe." },
    [4742] = { "Siegel des Aufstiegs", "Sucht die drei Edelsteine der Befehlsgewalt: den Edelstein der Gluthauer, den Edelstein der Felsspitzoger und den Edelstein der Blutäxte. Bringt sie zusammen mit dem unverzierten Siegel des Aufstiegs zu Vaelan zurück.\n\nVaelan nannte Euch auch die Namen der drei Generäle: Kriegsmeister Voone von den Gluthauern, Hochlord Omokk von den Felsspitzogern und Oberanführer Wyrmthalak von den Blutäxten." },
    [4743] = { "Siegel des Aufstiegs", "Reist zum Drachensumpf in den Düstermarschen. Sucht den alten Drachen Aschenschwinge auf und bekämpft ihn ohne Gnade, bis sein Wille gebrochen ist.\n\nIn genau diesem Moment müsst Ihr das ungeschmiedete Siegel des Aufstiegs vor der großen Bestie hinlegen. Dann müsst Ihr schnell die Kugel der drachischen Energie auf seine geschwächte Gestalt anwenden und die Kontrolle über seine geistigen Kräfte übernehmen. Kontrolliert die Bestie und zwingt die Flammen des schwarzen Drachenschwarms auf das ungeschmiedete Siegel des Aufstiegs!" },
    [4764] = { "Doomriggers Schnalle", "Bringt Mayara Wolkenglanz in der Brennenden Steppe Doomriggers Schnalle." },
    [4765] = { "Lieferung an Kronenbrunn", "Bringt Kronenbrunns Kiste zu Graf Remington Kronenbrunn nach Burg Sturmwind in Sturmwind." },
    [4768] = { "Die Dunkelsteinschrifttafel", "Bringt der Schattenmagierin Vivian Lagrave in Kargath die Dunkelsteinschrifttafel." },
    [4771] = { "Dämmerungstrickfalle", "Legt die Dämmerungstrickfalle in den Vorführraum von Scholomance. Besiegt Vectus und kehrt dann zu Betina Moppelzink zurück." },
    [4787] = { "Das uralte Ei", "Bringt das uralte Ei zu Yeh'kinya nach Tanaris." },
    [4788] = { "Die letzten Schrifttafeln", "Bringt Ausgrabungsleiter Eisenschuh in Tanaris die fünfte und sechste Schrifttafel von Mosh'aru." },
    [4808] = { "Felnok Stahlfeder", "Gebt Felnok Stahlfeder in der Ewigen Warte in Winterquell Tinkees Brief." },
    [4809] = { "Hörner der Eiswindschimären", "Beschafft Euch 8 unbeschädigte Hörner." },
    [4810] = { "Rückkehr zu Tinkee", "Bringt Tinkee Kesseldampf auf dem Flammenkamm in der Brennenden Steppe Felnoks Päckchen." },
    [4862] = { "Be-Öh-Es-Eh", "Reist zur Schwarzfelsspitze und sammelt 15 Spitzenspinneneier für Kibler.\n\nLogischerweise müsstet Ihr diese Eier in der Nähe von Spinnen finden." },
    [4866] = { "Muttermilch", "Ihr findet Mutter Glimmernetz im Herzen der Schwarzfelsspitze. Kämpft mit ihr und bringt sie dazu, Euch zu vergiften. Es kann gut sein, dass Ihr sie sogar töten müsst. Kehrt zum struppigen John zurück, sobald Ihr vergiftet seid, damit er Euch 'melken' kann." },
    [4867] = { "Urok Schreckensbote", "Lest Waroshs Rolle. Bringt Waroshs Mojo zu Warosh." },
    [4903] = { "Befehl des Kriegsherrn", "Tötet Hochlord Omokk, Kriegsmeister Voone und Oberanführer Wyrmthalak. Findet die wichtigen Schwarzfelsdokumente. Kehrt zum Kriegsherrn Bluthauer nach Kargath zurück, sobald Ihr diese Mission erledigt habt." },
    [4941] = { "Etriggs Weisheit", "Sprecht mit Etrigg in Orgrimmar. Wenn Ihr die Angelegenheit mit Etrigg besprochen habt, bittet Thrall um Rat.\n\nIhr erinnert Euch, dass Ihr Etrigg in Thralls Gemächern gesehen habt." },
    [4974] = { "Für die Horde!", "Begebt Euch zur Schwarzfelsspitze und tötet den Kriegshäuptling Rend Schwarzfaust. Nehmt seinen Kopf und kehrt nach Orgrimmar zurück." },
    [4981] = { "Agentin Bijou", "Begebt Euch zur Schwarzfelsspitze und findet heraus, was aus Bijou geworden ist." },
    [4982] = { "Bijous Habseligkeiten", "Sucht Bijous Habseligkeiten und bringt sie ihr. Ihr erinnert Euch daran, dass sie erwähnte, ihre Sachen auf der untersten Ebene der Stadt versteckt zu haben." },
    [4983] = { "Bijous Aufklärungsbericht", "Bringt Bijous Aufklärungsbericht zu Großmeister Lexlort nach Kargath." },
    [5001] = { "Bijous Habseligkeiten", "Sucht Bijous Habseligkeiten und bringt sie ihr. Viel Glück!" },
    [5002] = { "Nachricht an Maxwell", "Begebt Euch in die Brennende Steppe und leitet Bijous Informationen an Marschall Maxwell weiter." },
    [5047] = { "Finkle Einhorn, zu Euren Diensten!", "Sprecht mit Malyfous Düsterhammer in der Ewigen Warte." },
    [5063] = { "Kappe des Scharlachroten Wissenden", "Um die Kappe des scharlachroten Wissenden herzustellen, müsst Ihr die folgenden Dinge zu Malyfous Düsterhammer bringen: 1 makelloser Balg der Bestie; 5 ausgefranste Monstrositätenstickereien; 8 Arkankristalle; 5 verzauberte scharlachrote Fäden.\n\nIhr müsst außerdem 50 Goldstücke für die Herstellung des Gegenstandes zahlen." },
    [5065] = { "Die verlorenen Schrifttafeln von Mosh'aru", "Bringt Ausgrabungsleiter Eisenschuh in Tanaris die dritte und vierte Schrifttafel von Mosh'aru." },
    [5067] = { "Gamaschen von Arcana", "Um die Gamaschen von Arcana herzustellen, müsst Ihr die folgenden Dinge zu Malyfous Düsterhammer bringen: 1 makelloser Balg der Bestie; 5 ausgefranste Monstrositätenstickereien; 5 Arkanitbarren; 5 Einheiten Frostraunens Balsamierungsflüssigkeit.\n\nIhr müsst außerdem 50 Goldstücke für die Herstellung des Gegenstandes zahlen." },
    [5068] = { "Brustplatte des Blutdurstes", "Um die Brustplatte des Blutdurstes herzustellen, müsst Ihr die folgenden Dinge zu Malyfous Düsterhammer bringen: 1 makelloser Balg der Bestie; 10 ausgefranste Monstrositätenstickereien; 5 Arkanitbarren; 5 Häute des Schattens.\n\nIhr müsst außerdem 50 Goldstücke für die Herstellung des Gegenstandes zahlen." },
    [5081] = { "Maxwells Mission", "Reist zur Schwarzfelsspitze und schaltet Kriegsmeister Voone, Hochlord Omokk und Oberanführer Wyrmthalak aus." },
    [5089] = { "General Drakkisaths Befehl", "Bringt den Befehl von General Drakkisath zu Marschall Maxwell in der Brennenden Steppe." },
    [5102] = { "General Drakkisaths Niedergang", "Begebt Euch zur Schwarzfelsspitze und schaltet General Drakkisath aus." },
    [5122] = { "Das Medaillon des Glaubens" },
    [5125] = { "Aurius' Abrechnung" },
    [5126] = { "Lorax' Geschichte", "Sprecht mit Lorax. Hört, was er zu sagen hat." },
    [5127] = { "Die Dämonenschmiede", "Begebt Euch zur Schwarzfelsspitze und sucht Goraluk Hammerbruch. Erschlagt ihn und wendet dann die blutbefleckte Pike auf seine Leiche an. Nachdem seine Seele abgesaugt wurde, wird die Pike seelenbefleckt sein.\n\nIhr müsst außerdem die ungeschmiedete runenbedeckte Brustplatte finden.\n\nBringt die seelenbefleckte Pike und die ungeschmiedete runenbedeckte Brustplate zu Lorax in Winterquell." },
    [5160] = { "Die oberste Beschützerin", "Begebt Euch nach Winterquell und sucht Haleh. Gebt ihr Awbees Schuppe." },
    [5161] = { "Der Zorn des blauen Drachenschwarms", "Sprecht mit Haleh, wenn Ihr weitermachen wollt." },
    [5162] = { "Der Zorn des blauen Drachenschwarms", "Sprecht mit Jeziba in den Pestländern. Er wohnt in Andorhal." },
    [5164] = { "Verzeichnis der Abtrünnigen", "Lest das 'Verzeichnis der Abtrünnigen'." },
    [5166] = { "Brustplatte des chromatischen Drachenschwarms", "Um die Brustplatte des chromatischen Drachenschwarms zu schmieden, müsst Ihr die folgenden Gegenstände zu Jeziba dem 'Bildhauer' bringen:\n\n1 chromatischen Knochenpanzer.\n\n10 glänzende chromatische Schuppen.\n\n10 Einheiten Blut von Helden.\n\n10 ausgefranste Monstrositätenstickereien." },
    [5167] = { "Beinplatten des chromatischen Widersetzers", "Um die Beinplatten des chromatischen Widersetzers zu schmieden, müsst Ihr die folgenden Gegenstände zu Jeziba dem 'Bildhauer' bringen:\n\n1 chromatischer Knochenpanzer.\n\n10 glänzende chromatische Schuppen.\n\n10 Einheiten Blut von Helden.\n\n5 Häute des Schattens." },
    [5212] = { "Das Fleisch lügt nicht", "Sammelt 10 verseuchte Fleischproben in Stratholme und bringt sie zu Betina Moppelzink zurück. Ihr vermutet, dass Ihr besagte Fleischproben bei jeder Kreatur in Stratholme finden könnt." },
    [5213] = { "Der aktive Wirkstoff", "Reist nach Stratholme und durchsucht die Ziggurats. Sucht neue Geißeldaten und bringt sie zu Betina Moppelzink zurück." },
    [5214] = { "Der große Fras Siabi", "Sucht Fras Siabis Raucherladen in Stratholme und bergt einen Kasten von Siabis Tollem Tabak. Kehrt zu Smokey LaRue zurück, wenn Eure Aufgabe erledigt ist." },
    [5243] = { "Häuser der Heiligen", "Begebt Euch nach Stratholme im Norden. Durchsucht die Vorratskisten, die über die Stadt verstreut sind, und holt 5 Einheiten Weihwasser von Stratholme. Kehrt zu Leonidas Bartholomäus dem Geachteten zurück, wenn Ihr genug der gesegneten Flüssigkeit gesammelt habt." },
    [5251] = { "Der Archivar", "Reist nach Stratholme und sucht Archivar Galford vom Scharlachroten Kreuzzug. Vernichtet ihn und verbrennt das Scharlachrote Archiv." },
    [5262] = { "Die Wahrheit zeigt sich mit Macht", "Bringt den Kopf von Balnazzar zu Fürst Nicholas Zverenhoff in den Östlichen Pestländern." },
    [5263] = { "Übertroffen", "Zieht nach Stratholme und vernichtet Baron Totenschwur. Nehmt seinen Kopf und kehrt zu Fürst Nicholas Zverenhoff zurück." },
    [5264] = { "Lord Maxwell Tyrosus", "Sprecht mit Lord Maxwell Tyrosus. Er befindet sich in der Kirche." },
    [5265] = { "Der Argentumtresor", "Öffnet den Argentumtresor und nehmt Euch Eure Belohnung." },
    [5281] = { "Die ruhelosen Seelen", "Sucht Egan. Ihr wisst nur, dass er zuletzt in der Nähe von Stratholme gesehen wurde." },
    [5282] = { "Die ruhelosen Seelen", "Wendet Egans Blaster auf die geisterhaften und spektralen Bürger von Stratholme an. Wenn die ruhelosen Geister ihre geisterhaften Hüllen sprengen, wendet den Blaster erneut an - dann sind sie endlich frei!\n\nBefreit 15 ruhelose Seelen und kehrt zu Egan zurück." },
    [5341] = { "Das Familienvermögen der Barovs", "Begebt Euch zur Scholomance und holt das Familienvermögen der Barovs zurück. Dieses Vermögen besteht aus vier Besitzurkunden: Es sind die Besitzurkunde für Darrowehr, die Besitzurkunde für Brill, die Besitzurkunde für Tarrens Mühle und die Besitzurkunde für Süderstade. Kehrt zu Alexi Barov zurück, sobald die Aufgabe erledigt ist." },
    [5342] = { "Der letzte Barov", "Begebt Euch zum Zugwindlager - Territorium der Allianz - und ermordet Weldon Barov. Nehmt seinen Kopf und kehrt zu Alexi Barov zurück.\n\nSeid gewarnt, Weldon wird wahrscheinlich gut von Abschaum der Allianz geschützt." },
    [5343] = { "Das Familienvermögen der Barovs", "Begebt Euch zur Scholomance und holt das Familienvermögen der Barovs zurück. Dieses Vermögen besteht aus vier Besitzurkunden: Es sind die Besitzurkunde für Darrowehr, die Besitzurkunde für Brill, die Besitzurkunde für Tarrens Mühle und die Besitzurkunde für Süderstade. Kehrt zu Weldon Barov zurück, sobald die Aufgabe erledigt ist." },
    [5344] = { "Der letzte Barov", "Begebt Euch zum Bollwerk - Territorium der Horde - und ermordet Alexi Barov. Nehmt seinen Kopf und kehrt zu Weldon Barov zurück.\n\nSeid gewarnt, Alexi wird wahrscheinlich gut durch Abschaum der Horde geschützt." },
    [5382] = { "Doktor Theolen Krastinov, der Schlächter", "Sucht Doktor Theolen Krastinov in Scholomance. Vernichtet ihn, verbrennt dann die Überreste von Eva Sarkhoff und die Überreste von Lucien Sarkhoff. Kehrt zu Eva Sarkhoff zurück, sobald Ihr die Aufgabe erfüllt habt." },
    [5384] = { "Kirtonos der Herold", "Kehrt mit dem Blut Unschuldiger zur Scholomance zurück. Sucht die Veranda und legt das Blut der Unschuldigen in die Kohlenpfanne. Kirtonos wird kommen, um sich von Eurer Seele zu nähren.\n\nKämpft tapfer, gebt keinen Fußbreit nach! Vernichtet Kirtonos und kehrt zu Eva Sarkhoff zurück." },
    [5461] = { "Der Mensch Ras Frostraunen", "Reist in das Arathihochland zu den Ruinen von Stromgarde. Durchsucht Stromgarde nach einem Andenken der Erinnerung. Wenn Ihr einen solchen Gegenstand findet, kehrt mit ihm zu Magistrat Marduk zurück." },
    [5462] = { "Der Sterbende Ras Frostraunen", "Reist zur Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern und sucht Leonidas Bartholomäus den Geachteten auf. Zeigt ihm das Andenken der Erinnerung und berichtet ihm alles, was Ihr entdeckt habt." },
    [5463] = { "Menethils Geschenk", "Begebt Euch nach Stratholme und sucht Menethils Geschenk. Platziert das Andenken der Erinnerung auf dem unheiligen Boden." },
    [5464] = { "Menethils Geschenk", "Bringt das seelengebundene Andenken zu Leonidas Bartholomäus in den Östlichen Pestländern." },
    [5465] = { "Seelengebundenes Andenken", "Kehrt zu Magistrat Marduk in Darrowehr zurück. Zeigt ihm das seelengebundene Andenken." },
    [5466] = { "Der Lich Ras Frostraunen", "Sucht Ras Frostraunen in Scholomance. Wenn Ihr ihn gefunden habt, wendet das seelengebundene Andenken auf sein untotes Antlitz an. Solltet Ihr ihn erfolgreich in einen Sterblichen zurückverwandeln können, dann schlagt ihn nieder und nehmt den menschlichen Kopf von Ras Frostraunen an Euch. Bringt den Kopf zu Magistrat Marduk." },
    [5515] = { "Krastinovs Tasche der Schrecken", "Sucht nach Jandice Barov in Scholomance und vernichtet sie. Entnehmt ihrer Leiche Krastinovs Tasche der Schrecken. Bringt die Tasche zu Eva Sarkhoff." },
    [5518] = { "Der Ogeranzug der Gordok", "Bringt 4 Runenstoffballen, 8 Stücke unverwüstliches Leder, 2 Runenfaden und etwas Ogergerbemittel zu Knot Zwingschraub. Momentan ist er im Gordokflügel von Düsterbruch angekettet." },
    [5519] = { "Der Ogeranzug der Gordok" },
    [5522] = { "Leonidas Bartholomäus", "Bringt die gefrorenen Eier zu Leonidas Bartholomäus in den Östlichen Pestländern." },
    [5525] = { "Befreit Knot!" },
    [5526] = { "Die Splitter der Teufelsranke", "Sucht die Teufelsranke in Düsterbruch und nehmt einen Teufelsrankensplitter mit Euch. Aller Wahrscheinlichkeit nach werdet Ihr Alzzin den Wildformer töten müssen, um an die Teufelsranke zu gelangen. Benutzt das Reliquiar der Reinheit, um darin den Splitter sicher zu versiegeln, und bringt das versiegelte Reliquiar zu Rabine Saturna in Nachthafen auf der Mondlichtung." },
    [5527] = { "Ein Reliquiar der Reinheit", "Reist nach Silithus und sucht in den Ruinen des Südwindpostens nach einem Reliquiar der Reinheit. Sollte Eure Suche Erfolg haben, kehrt zu Rabine Saturna in Nachthafen auf der Mondlichtung zurück." },
    [5528] = { "Der Gordokgeschmackstest" },
    [5529] = { "Verseuchte Jungtiere", "Tötet 20 verseuchte Jungtiere und kehrt dann zu Betina Moppelzink bei der Kapelle des Hoffnungsvollen Lichts zurück." },
    [5531] = { "Betina Moppelzink", "Bringt die gefrorenen Eier zu Betina Moppelzink." },
    [5542] = { "Dämonenhunde", "Erschlagt 20 kleine Seuchenhunde, 5 Seuchenhunde und 5 rasende Seuchenhunde. Kehrt zu Tirion Fordring zurück, sobald Ihr die Aufgabe erfüllt habt." },
    [5543] = { "Blutgefärbter Himmel", "Erschlagt 30 Seuchenfledermäuse und kehrt zu Tirion Fordring zurück." },
    [5544] = { "Aassammlung", "Sucht nach den Aaslarven und Aasverschlingern dieses Gebiets. Erschlagt sie und sammelt ihr Fleisch. Kehrt zu Tirion Fordring zurück, wenn Ihr 15 Scheiben Aaswurmfleisch gesammelt habt." },
    [5582] = { "Gesunde Großdrachenschuppe", "Bringt die gesunde Großdrachenschuppe zu Betina Moppelzink bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern." },
    [5722] = { "Die Suche nach dem verloren gegangenen Ranzen", "Sucht im Flammenschlund nach Maur Grimmtotems Leiche und durchsucht sie nach interessanten Gegenständen." },
    [5723] = { "Die Kraft des Feindes wird auf die Probe gestellt", "Sucht in Orgrimmar nach dem Flammenschlund, tötet dann 8 Flammenschlundtroggs und 8 Schamanen der Flammenschlundtroggs und kehrt anschließend zu Rahauro in Donnerfels zurück." },
    [5724] = { "Wiederbeschaffung des verloren gegangenen Ranzens", "Bringt den Grimmtotemranzen zu Rahauro nach Donnerfels." },
    [5725] = { "Die Macht zu Zerstören...", "Bringt die Bücher 'Schattenzauber' und 'Zauberformeln aus dem Nether' zu Varimathras nach Unterstadt." },
    [5726] = { "Verborgene Feinde", "Bringt ein Insigne des Leutnants zu Thrall nach Orgrimmar." },
    [5727] = { "Verborgene Feinde", "Bringt Neeru Feuerklinge das Insigne des Offiziers und sprecht mit ihm. Seht, ob er Euch glaubt, dass Ihr ein Mitglied der Brennenden Klinge seid, und kehrt dann zu Thrall nach Orgrimmar zurück." },
    [5728] = { "Verborgene Feinde", "Tötet Bazzalan und Jergosh den Herbeirufer, bevor Ihr zu Thrall nach Orgrimmar zurückkehrt." },
    [5729] = { "Verborgene Feinde", "Sprecht mit Neeru Feuerklinge in Orgrimmar." },
    [5730] = { "Verborgene Feinde", "Sprecht in Orgrimmar mit Thrall und berichtet ihm, was Ihr erfahren habt." },
    [5742] = { "Erlösung", "Hört Euch an, was Tirion Fordring zu sagen hat." },
    [5761] = { "Vernichtung der Bestie", "Begebt Euch in den Flammenschlund und erschlagt Taragaman den Hungerleider. Bringt anschließend dessen Herz zu Neeru Feuerklinge nach Orgrimmar." },
    [5781] = { "Von vergessenen Erinnerungen", "Begebt Euch zum Tiefgewölbe im südlichsten Abschnitt der Östlichen Pestländer und sucht nach Taelans Hammer. Kehrt zu Tirion Fordring zurück, sobald Ihr Eure Mission abgeschlossen habt." },
    [5845] = { "Von verlorener Ehre", "Reist ins Nordtal im nordöstlichsten Gebiet der Östlichen Pestländer und sucht nach dem Symbol der verlorenen Ehre. Kehrt zu Tirion Fordring zurück, sobald Ihr Eure Mission abgeschlossen habt." },
    [5846] = { "Von Liebe und Familie", "Begebt Euch zur Insel Darrowehr im südlich-zentralen Bereich der Pestländer und sucht nach Hinweisen, wo sich das Gemälde befinden könnte." },
    [5848] = { "Von Liebe und Familie", "Begebt Euch nach Stratholme im nördlichen Teil der Pestländer. In der Scharlachroten Bastion findet Ihr das Gemälde 'Von Liebe und Familie', das zwischen anderen Gemälden versteckt ist und auf dem die Zwillingsmonde unserer Welt abgebildet sind.\n\nBringt das Gemälde zu Tirion Fordring." },
    [5861] = { "Myranda suchen", "Begebt Euch zu Uthers Grabmal in den Südlichen Pestländern. Zeigt Myranda der Vettel Tirions Geschenk." },
    [5862] = { "Scharlachrote Täuschung", "Sprecht mit Myranda, um die Scharlachrote Illusion zu erhalten. Begebt Euch nach Herdweiler, während Ihr unter dem Einfluss der Scharlachroten Illusion steht, und übergebt dem Hochlord Taelan Fordring Tirions Geschenk.\n\nHerdweiler liegt im Norden, Taelan dürfte sich in der Burg Mardenholde aufhalten." },
    [5944] = { "In den Träumen", "Geleitet Taelan Fordring aus Herdweiler hinaus." },
    [6022] = { "Töten zu einem bestimmten Zweck", "Begebt Euch zu Corins Kreuzung im Osten und besiegt die Mitglieder der Geißel, die in der Stadt leben. Sammelt 7 Stücke lebendige Fäulnis in unter 10 Minuten. Zerstoßt die lebendige Fäulnis mit Mörser und Stößel zu geronnener Fäulnis." },
    [6042] = { "Die kleinen Ärgernisse des Un-Lebens", "Erschlagt 20 giftige Seuchenfledermäuse und 10 monströse Seuchenfledermäuse. Kehrt zu Nathanos Pestrufer zurück, wenn Ihr fertig seid." },
    [6133] = { "Das Ersuchen des Waldläuferlords", "Begebt Euch zur nördlichsten Grenze der Östlichen Pestländer und bringt die Registratur von Quel'Thalas zurück. Der Gegenstand befindet sich irgendwo in der Jagdhütte von Quel'Lithien.\n\nAußerdem müsst Ihr 8 Waldläufer, 8 Pfadschreiter und 8 Waldarbeiter töten." },
    [6135] = { "Dämmerschwinge, oh, wie ich Euch hasse...", "Sucht Dämmerschwinge und tötet ihn. Nehmt ein Büschel vom Fell Dämmerschwinges und bringt es zu Nathanos Pestrufer.\n\nMan sagt, dass Dämmerschwinge nördlich von hier durch das Land streift." },
    [6136] = { "Der Korpulente", "Sucht in den nördlichen Wüsten der Östlichen Pestländer nach Blutschlinger und vernichtet ihn. Kehrt zu Nathanos Pestrufer zurück, sobald Ihr diese Mission erledigt habt." },
    [6163] = { "Ramstein", "Reist nach Stratholme und tötet Ramstein den Würger. Bringt seinen Kopf als Souvenir zu Nathanos." },
    [6402] = { "Treffen in Sturmwind", "Reist nach Sturmwind und begebt Euch zu den Stadttoren. Sprecht mit Knappe Rowe, damit er Marschall Windsor über Eure Ankunft informiert." },
    [6403] = { "Die große Maskerade", "Folgt Reginald Windsor durch Sturmwind. Schützt ihn vor Gefahren!" },
    [6501] = { "Das Großdrachenauge", "Ihr müsst die Welt nach jemandem absuchen, der fähig ist, die Macht des Fragments des Großdrachenauges wieder herzustellen. Die einzige Information, die Ihr über ein solches Wesen besitzt ist, dass es existiert." },
    [6502] = { "Drachenfeueramulett", "Ihr müsst das Blut des schwarzen Drachenhelden von General Drakkisath bekommen. Ihr findet Drakkisath in seinem Thronsaal hinter den Hallen des Aufstiegs auf der Schwarzfelsspitze." },
    [6521] = { "Eine unheilige Allianz", "Bringt den Kopf von Botschafter Malcin zu Bragor Blutfaust nach Unterstadt." },
    [6522] = { "Eine unheilige Allianz", "Bringt die kleine Rolle zu Bragor Blutfaust im Königsviertel von Unterstadt." },
    [6561] = { "Schurkerei in der Tiefschwarzen Grotte", "Bringt den Kopf von Zwielichtfürst Kelris zu Bashana Runentotem in Donnerfels." },
    [6562] = { "Ärger in der Tiefe", "Sprecht im Eschental mit Je'neu Sancrea." },
    [6563] = { "Die Essenz von Aku'mai", "Bringt 20 Saphire von Aku'mai zu Je'neu Sancrea im Eschental." },
    [6564] = { "Treue zu den Alten Göttern", "Bringt die durchfeuchtete Notiz zu Je'neu Sancrea im Eschental." },
    [6565] = { "Treue zu den Alten Göttern", "Tötet Lorgus Jett." },
    [6566] = { "Was der Wind erzählt", "Hört Thrall zu." },
    [6567] = { "Der Champion der Horde", "Sucht in Schattenflucht in Desolace nach Rokaro." },
    [6568] = { "Meisterin der Illusionen", "Überbringt Myranda der Vettel in den Westlichen Pestländern Rokaros Brief." },
    [6569] = { "Oculus-Illusionen", "Reist zur Schwarzfelsspitze und sammelt 20 schwarze Drachenbrutaugen. Kehrt zu Myranda der Vettel zurück, sobald Ihr die Aufgabe erfüllt habt." },
    [6570] = { "Aschenschwinge", "Reist zum Drachensumpf in den Düstermarschen und begebt Euch in Aschenschwinges Bau. Sobald Ihr darin seid, tragt das Amulett der drachischen Subversion und sprecht mit Aschenschwinge." },
    [6582] = { "Die Prüfung der Schädel, Seher", "Ihr müsst Seher, den Champion der blauen Großdrachen, finden und ihn töten. Schlagt seinem Kadaver den Schädel ab und bringt ihn zu Aschenschwinge.\n\nIhr wisst, dass Seher in Winterquell zu finden ist." },
    [6583] = { "Die Prüfung der Schädel, Somnus", "Vernichtet den Drachenchampion des grünen Drachenschwarms, Somnus. Nehmt seinen Schädel und bringt ihn zu Aschenschwinge zurück." },
    [6584] = { "Die Prüfung der Schädel, Chronalis", "Chronalis, ein Kind Nozdormus, bewacht die Höhlen der Zeit in der Tanariswüste. Vernichtet ihn und bringt seinen Schädel zu Aschenschwinge." },
    [6585] = { "Die Prüfung der Schädel, Axtroz", "Begebt Euch nach Grim Batol und spürt Axtroz auf, den Drachenchampion des roten Drachenschwarms. Vernichtet ihn und nehmt seinen Schädel. Bringt den Schädel zu Aschenschwinge zurück." },
    [6601] = { "Aufstieg...", "Mir scheint, als sei die Charade jetzt vorüber. Ihr wisst, dass das Amulett der drachischen Unterwanderung, das Myranda die Vettel für Euch erschuf, auf der Schwarzfelsspitze nicht funktioniert. Vielleicht solltet Ihr Rokaro aufsuchen und ihm Eure Notlage erklären. Zeigt ihm das glanzlose Drachenfeueramulett. Er wird hoffentlich wissen, was als Nächstes zu tun ist." },
    [6602] = { "Blut des schwarzen Großdrachenhelden", "Begebt Euch zur Schwarzfelsspitze und tötet General Drakkisath. Sammelt sein Blut und bringt es zu Rokaro." },
    [6626] = { "Ein Hort des Bösen", "Tötet 8 Schlachtwachen der Klingenhauer, 8 Dornenwirker der Klingenhauer und 8 Kultistinnen der Totenköpfe und kehrt dann zu Myriam Mondsang nahe dem Eingang zu den Hügeln der Klingenhauer zurück." },
    [6627] = { "Test der Lehre", "Beantwortet Braug Dämmergeists Frage richtig und sprecht dann erneut mit ihm. Er wird immer noch im Steinkrallengebirge sein, wenn Ihr bereit seid." },
    [6628] = { "Test der Lehre", "Beantwortet Parqual Fintallas' Frage richtig und sprecht dann erneut mit ihm. Er wird immer noch in Unterstadt sein, wenn Ihr bereit seid." },
    [6804] = { "Vergiftetes Wasser", "Wendet den Aspekt von Neptulon auf die vergifteten Elementare der Östlichen Pestländer an. Bringt 12 disharmonische Armschienen sowie den Aspekt von Neptulon zu Fürst Hydraxis in Azshara." },
    [6805] = { "Stürmer und Rumpler", "Tötet 15 Staubstürmer und 15 Wüstenrumpler und kehrt dann zu Fürst Hydraxis in Azshara zurück." },
    [6821] = { "Auge des Glutsehers", "Bringt das Auge des Glutsehers zu Fürst Hydraxis in Azshara." },
    [6822] = { "Der Geschmolzene Kern", "Tötet 1 Feuerlord, 1 geschmolzenen Riesen, 1 uralten Kernhund sowie 1 Lavawoger und kehrt dann zu Fürst Hydraxis in Azshara zurück." },
    [6823] = { "Agent von Hydraxis", "Verdient Euch eine geehrte Fraktion bei den hydraxianischen Wasserlords und sprecht dann mit Fürst Hydraxis in Azshara." },
    [6824] = { "Hände des Feindes", "Bringt die Hände von Lucifron, Sulfuron, Gehennas und Shazzrah zu Fürst Hydraxis in Azshara." },
    [6921] = { "Inmitten der Ruinen", "Bringt den Tiefenkern zu Je'neu Sancrea beim Außenposten von Zoram'gar im Eschental." },
    [6922] = { "Baron Aquanis", "Bringt die seltsame Wasserkugel zu Je'neu Sancrea in der Tiefschwarzen Grotte." },
    [6981] = { "Der leuchtende Splitter", "Begebt Euch nach Ratschet, um jemanden zu finden, der Euch mehr über den leuchtenden Splitter sagen kann.\n\nLiefert dann den Splitter ab, wie Ihr angewiesen wurdet." },
    [7028] = { "Dunkles Böses", "Sammelt 15 theradrische Kristallschnitzereien für Trista in Desolace." },
    [7029] = { "Schlangenzunges Verderbnis", "Füllt die beschichtete himmelblaue Phiole am orangefarbenen Kristallteich in Maraudon.\n\nBenutzt die gefüllte himmelblaue Phiole mit den Schlangenstrunkranken, damit der verderbte Noxxiousspross herausgezwungen wird.\n\nHeilt 8 Pflanzen, indem Ihr diesen Noxxiousspross tötet und kehrt dann zu Vark Schlachtnarbe in Schattenflucht zurück." },
    [7041] = { "Schlangenzunges Verderbnis", "Füllt die beschichtete himmelblaue Phiole am orangefarbenen Kristallteich in Maraudon.\n\nBenutzt die gefüllte himmelblaue Phiole mit den Schlangenstrunkranken, damit der verderbte Noxxiousspross herausgezwungen wird.\n\nHeilt 8 Pflanzen, indem Ihr diesen Noxxiousspross tötet und kehrt dann zu Talendria an der Nijelspitze zurück." },
    [7044] = { "Legenden von Maraudon", "Beschafft die beiden Teile des Szepters von Celebras: den Celebriangriff und den Celebriandiamanten.\n\nFindet einen Weg, um mit Celebras zu sprechen." },
    [7046] = { "Das Szepter von Celebras", "Helft Celebras dem Erlösten, während er das Szepter von Celebras herstellt.\n\nSprecht mit ihm, nachdem das Ritual vollendet ist." },
    [7064] = { "Verderbnis von Erde und Samenkorn", "Tötet Prinzessin Theradras und kehrt zu Selendra in der Nähe von Schattenflucht in Desolace zurück." },
    [7065] = { "Verderbnis von Erde und Samenkorn", "Erschlagt Prinzessin Theradras und kehrt zum Bewahrer Marandis an der Nijelspitze in Desolace zurück." },
    [7066] = { "Samenkorn des Lebens", "Sucht Remulos bei der Mondlichtung auf und gebt ihm das Samenkorn des Lebens." },
    [7067] = { "Die Anweisungen des Pariahs", "Lest die Anweisungen des Pariahs. Beschafft Euch danach das Amulett der Vereinigung von Maraudon und bringt es dem Zentaurenpariah im südlichen Desolace." },
    [7068] = { "Schattensplitter", "Sammelt 10 Schattensplitter aus Maraudon und bringt sie zu Uthel'nay nach Orgrimmar." },
    [7070] = { "Schattensplitter", "Sammelt 10 Schattensplitter in Maraudon und bringt sie zu Erzmagier Tervosh in den Düstermarschen." },
    [7201] = { "Das letzte Element", "Begebt Euch in die Schwarzfelstiefen und beschafft 10 Essenzen der Elemente. Euer erster Gedanke ist, die Golems und die Schöpfer der Golems zu suchen. Doch Ihr erinnert Euch, dass Vivian Lagrave auch etwas von Elementaren vor sich hingemurmelt hat." },
    [7429] = { "Befreit Knot!" },
    [7441] = { "Pusillin und der Älteste Azj'Tordin", "Reist nach Düsterbruch und macht den Dämonen Pusillin ausfindig. Überzeugt ihn mit allen Mitteln davon, Euch Azj'Tordin's Buch der Zauberformeln zu geben.\n\nKehrt mit dem Buch zu Az'Tordin, beim Larisspavillon in Feralas, zurück." },
    [7461] = { "Der innere Wahnsinn", "Zerstört alle Wächter, die um die 5 Pylonen herumstehen, welche Immol'thars Gefängnis mit Energie versorgen. Sobald die Pylone deaktiviert wurden, wird sich das Kraftfeld, das Immol'thar umgibt, auflösen.\n\nBetretet Immol'thars Gefängnis und vernichtet den verdorbenen Dämonen. Anschließend müsst Ihr Prinz Tortheldrin im Athenaeum entgegentreten.\n\nKehrt nach Abschluss der Aufgabe zur uralten Shen'dralar im Hof zurück." },
    [7462] = { "Der Schatz der Shen'dralar", "Kehrt in das Athenaeum zurück und sucht den Schatz der Shen'dralar. Nehmt Euch Eure Belohnung!" },
    [7463] = { "Arkane Erfrischung", "Reist nach Düsterbruch in das Wucherborkenviertel und besiegt den Wasserelementar Hydrobrut. Kehrt anschließend mit der Hydrobrutessenz zum Wissenshüter Lydros im Athenaeum zurück." },
    [7481] = { "Elfische Legenden", "Sucht in Düsterbruch nach Kariel Winthalus. Meldet Euch anschließend bei dem Weisen Korolusk in Camp Mojache." },
    [7482] = { "Elfische Legenden", "Sucht in Düsterbruch nach Kariel Winthalus. Meldet Euch anschließend bei der Gelehrten Runendorn in der Mondfederfeste." },
    [7483] = { "Buchband der Schnelligkeit", "Bringt ein Buchband der Schnelligkeit, 1 makellosen schwarzen Diamanten, 2 große glänzende Splitter und 2-mal das Blut von Helden, zum Wissenshüter Lydros in Düsterbruch, um ein Arkanum der Schnelligkeit zu erhalten." },
    [7484] = { "Buchband des Fokus", "Bringt ein Buchband des Fokus, 1 makellosen schwarzen Diamanten, 4 große glänzende Splitter und 2-mal Schattenhaut, zum Wissenshüter Lydros in Düsterbruch, um ein Arkanum des Fokus zu erhalten." },
    [7485] = { "Buchband des Schutzes", "Bringt ein Buchband des Schutzes, 1 makellosen schwarzen Diamanten, 2 große glänzende Splitter und 1 ausgefranste Monstrositätenstickerei zum Wissenshüter Lydros in Düsterbruch, um ein Arkanum des Schutzes zu erhalten." },
    [7486] = { "Die Belohnung eines Helden", "Nehmt Eure Belohnung aus Hydraxis' Kasten." },
    [7488] = { "Lethtendris' Netz", "Bringt Lethtendris' Netz zu Latronicus Mondspeer in der Mondfederfeste in Feralas." },
    [7489] = { "Lethtendris' Netz", "Bringt Lethtendris' Netz zu Talo Dornhuf im Camp Mojache in Feralas." },
    [7490] = { "Sieg für die Horde", "Bringt Onyxias Kopf zu Garrosh in Orgrimmar." },
    [7491] = { "Für alle sichtbar", "Sucht Oberanführer Runthak im Tal der Stärke auf." },
    [7493] = { "Die Reise beginnt erst" },
    [7495] = { "Sieg für die Allianz", "Bringt Onyxias Kopf zu König Varian Wrynn in Sturmwind." },
    [7496] = { "Gute Zeiten feiern", "Sucht Major Mattingly im Tal der Helden auf." },
    [7497] = { "Die Reise beginnt erst" },
    [7503] = { "Das größte Volk von Jägern", "Bringt das Buch seinen rechtmäßigen Besitzern zurück." },
    [7507] = { "Forors Kompendium", "Bringt Forors Kompendium des Drachentötens zurück in das Athenaeum." },
    [7508] = { "Das Schmieden von Quel'Serrar", "Bringt dem Wissenshüter Lydros die stumpfe und glanzlose Elfenklinge." },
    [7509] = { "Das Schmieden von Quel'Serrar", "Bringt Onyxia dazu, ihren Feueratem auf die noch unerhitzte Klinge zu benutzen. Sobald dies geschehen ist, hebt die erhitzte Klinge wieder auf. Doch seid gewarnt, die erhitzte Klinge wird nicht auf ewig erhitzt bleiben - behaltet also die Zeit im Auge.\n\nZuletzt müsst Ihr das Biest töten und die uralte erhitzte Klinge in ihren Leib rammen. Kehrt anschließend zu mir zurück und Quel'Serrar wird Euer sein." },
    [7562] = { "Mor'zul Blutbringer", "Sprecht mit Mor'zul Blutbringer beim Altar der Stürme in der Brennenden Steppe." },
    [7563] = { "Kochendes Blut", "Mor'zul Blutbringer in der Brennenden Steppe möchte, dass Ihr ihm 30 Flaschen mit dem Blut der tobenden Bestien bringt." },
    [7564] = { "Wildaug", "Bringt den Behälter mit Blut zu Gorzeeki Wildaug beim Altar der Stürme in der Brennenden Steppe." },
    [7629] = { "Wichtellieferung", "Bringt den Wichtel im Glas in das Alchemielabor in Scholomance. Bringt das Glas nach der Herstellung des Pergaments zurück zu Gorzeeki Wildaug." },
    [7637] = { "Ein Opfer darbieten", "Reist nach Eisenschmiede und besorgt Euch Hohepriester Rohans Weihrauchschwenker. Eine Spende von 150 Gold wird erforderlich sein, um es zu bekommen." },
    [7638] = { "Lord Grayson Schattenbruch", "Sprecht mit Lord Grayson Schattenbruch im Kathedralenviertel von Sturmwind." },
    [7639] = { "Lass Gerechtigkeit walten", "Bringt den Weihrauchschwenker zu Lord Grayson Schattenbruch in Sturmwind zurück." },
    [7640] = { "Der Exorzismus des Schreckenstals", "Vertreibt mithilfe des Weihrauchschwenkers die Geister im Schreckenstal. Vernichtet 25 Schreckenstalgeister und kehrt anschließend zu Lord Grayson Schattenbruch im Kathedralenviertel von Sturmwind zurück." },
    [7641] = { "Grimand Elmores Werk", "Sprecht mit Grimand Elmore im Zwergendistrikt von Sturmwind." },
    [7642] = { "Fünf Dinge", "Bringt 40 Lagen Runenstoff, 6 Arkanitbarren, 10 Arthas' Tränen, 5 Phiolen Weihwasser aus Stratholme und 150 Gold zu Grimand Elmore im Zwergendistrikt von Sturmwind." },
    [7643] = { "Der uralte Pferdegeist", "Beschafft spezielles Pferdefutter, mit dem man ein Geisterpferd füttern kann. Merideth Carlson in Süderstade scheint dafür eine recht gute Quelle zu sein.\n\nReist anschließend nach Düsterbruch in Feralas und tötet Tendris Wucherborke. Dies wird den uralten Pferdegeist befreien. Füttert den Geist zur Beruhigung mit dem speziellen Pferdefutter. Gebt dem Pferdegeist das Arkanitpferdegeschirr, um es segnen zu lassen." },
    [7644] = { "Gesegnetes Arkanitpferdegeschirr", "Kehrt mit dem gesegneten Arkanitpferdegeschirr zu Lord Grayson Schattenbruch in das Kathedralenviertel von Sturmwind zurück." },
    [7646] = { "Das Orakel der Anrufung", "Bringt Lord Grayson Schattenbruch im Kathedralenviertel von Sturmwind einen azerothischen Diamanten und einen makellosen schwarzen Diamanten." },
    [7667] = { "Materielle Unterstützung", "Wenn Ihr Sagorne Gratläufer im Tal der Weisheit von Orgrimmar helfen wollt, so bringt ihm einen azerothischen und einen makellosen schwarzen Diamanten." },
    [7668] = { "Die Bedrohung durch Schattensichel", "Wendet das Orakel der Anrufung inmitten des Kellergewölbes des Großen Ossuariums in Scholomance an. Ihr werdet damit Geister herbeirufen, die es zu bekämpfen gilt. Nach Vernichtung dieser Geister wird der Todesritter Schattensichel auftauchen; besiegt ihn.\n\nBringt Schattensichels Kopf zu Sagorne Gratläufer im Tal der Weisheit in Orgrimmar." },
    [7669] = { "Erneut im Großen Ossuarium" },
    [7761] = { "Schwarzfausts Befehl", "Das war ja vielleicht mal ein dummer Orc. Es sieht so aus, als müsstet Ihr dieses Brandzeichen finden, um an das Mal von Drakkisath zu gelangen. Damit sollte sich die Befehlskugel aktivieren lassen.\n\nDem Brief zufolge, wird das Brandzeichen von General Drakkisath bewacht. Vielleicht solltet Ihr diesem Hinweis nachgehen." },
    [7848] = { "Abstimmung mit dem Kern", "Begebt Euch zum Portal in den Schwarzfelstiefen, das in den Geschmolzenen Kern führt, und findet ein Kernfragment. Kehrt mit dem Fragment zu Lothos Felsspalter im Schwarzfels zurück." },
    [7877] = { "Der Schatz der Shen'dralar", "Kehrt in das Athenaeum zurück und sucht den Schatz der Shen'dralar. Nehmt Euch Eure Belohnung!" },
    [8181] = { "Konfrontiert Yeh'kinya", "Sprecht mit Yeh'kinya." },
    [8182] = { "Die Hand von Rastakhan", "Sprecht mit Molthor im Schlingendorntal." },
    [8905] = { "Ein aufrichtiges Angebot", "Sammelt 15 Blutproben aus Winterquell und bringt sie zusammen mit 20 Gold und einem Paar Armschienen des Wildherzens zu Deliana in Eisenschmiede." },
    [8906] = { "Ein aufrichtiges Angebot", "Sammelt 15 Blutproben aus Winterquell und bringt sie zusammen mit 20 Gold und einem Paar Bestienjägerbindungen zu Deliana in Eisenschmiede." },
    [8907] = { "Ein aufrichtiges Angebot", "Sammelt 15 Blutproben aus Winterquell und bringt sie zusammen mit 20 Gold und einem Paar Bindungen des Magisters zu Deliana in Eisenschmiede." },
    [8908] = { "Ein aufrichtiges Angebot", "Sammelt 15 Blutproben aus Winterquell und bringt sie zusammen mit 20 Gold und einem Paar Armschienen des Lichts zu Deliana in Eisenschmiede." },
    [8909] = { "Ein aufrichtiges Angebot", "Sammelt 15 Blutproben aus Winterquell und bringt sie zusammen mit 20 Gold und einem Paar Armschienen des Gläubigen zu Deliana in Eisenschmiede." },
    [8910] = { "Ein aufrichtiges Angebot", "Sammelt 15 Blutproben aus Winterquell und bringt sie zusammen mit 20 Gold und einem Paar Armschienen der Schattenkunst zu Deliana in Eisenschmiede." },
    [8911] = { "Ein aufrichtiges Angebot", "Sammelt 15 Blutproben aus Winterquell und bringt sie zusammen mit 20 Gold und einem Paar Armschienen der Furcht zu Deliana in Eisenschmiede." },
    [8912] = { "Ein aufrichtiges Angebot", "Sammelt 15 Blutproben aus Winterquell und bringt sie zusammen mit 20 Gold und einem Paar Armschienen der Ehre zu Deliana in Eisenschmiede." },
    [8913] = { "Ein aufrichtiges Angebot", "Sammelt 15 Giftproben aus Silithus und bringt sie zusammen mit 20 Gold und einem Paar Armschienen des Wildherzens zu Mokvar in Orgrimmar zurück." },
    [8914] = { "Ein aufrichtiges Angebot", "Sammelt 15 Giftproben aus Silithus und bringt sie zusammen mit 20 Gold und einem Paar Bestienjägerbindungen zu Mokvar in Orgrimmar zurück." },
    [8915] = { "Ein aufrichtiges Angebot", "Sammelt 15 Giftproben aus Silithus und bringt sie zusammen mit 20 Gold und einem Paar Bindungen des Magisters zu Mokvar in Orgrimmar zurück." },
    [8916] = { "Ein aufrichtiges Angebot", "Sammelt 15 Giftproben aus Silithus und bringt sie zusammen mit 20 Gold und einem Paar Armschienen des Gläubigen zu Mokvar in Orgrimmar zurück." },
    [8917] = { "Ein aufrichtiges Angebot", "Sammelt 15 Giftproben aus Silithus und bringt sie zusammen mit 20 Gold und einem Paar Armschienen der Schattenkunst zu Mokvar in Orgrimmar zurück." },
    [8918] = { "Ein aufrichtiges Angebot", "Sammelt 15 Giftproben aus Silithus und bringt sie zusammen mit 20 Gold und einem Paar Bindungen der Elemente zu Mokvar in Orgrimmar zurück." },
    [8919] = { "Ein aufrichtiges Angebot", "Sammelt 15 Giftproben aus Silithus und bringt sie zusammen mit 20 Gold und einem Paar Armschienen der Furcht zu Mokvar in Orgrimmar zurück." },
    [8920] = { "Ein aufrichtiges Angebot", "Sammelt 15 Giftproben aus Silithus und bringt es zusammen mit 20 Gold und einem Paar Armschienen der Ehre zu Mokvar in Orgrimmar zurück." },
    [8921] = { "Der Ektoplasmadestillierer", "Kehrt mit einem empfindlichen Arkanitwandler, 4 großen ewigen Essenzen, 10 Flaschen Steinschuppenöl, 25 Einheiten Vulkanasche und 40 Gold im Gepäck zu Mux Manamix in Gadgetzan zurück." },
    [8922] = { "Ein übernatürlicher Apparat", "Bringt den versiegelten Blutbehälter zu Mux Manamix in Gadgetzan." },
    [8923] = { "Ein übernatürlicher Apparat", "Bringt den versiegelten Giftbehälter zu Mux Manamix in Gadgetzan." },
    [8924] = { "Ektoplasmajagd", "Benutzt den Ektoplasmadestillierer in der Nähe von schemenhaften Untoten, um 12 Einheiten versengtes Ektoplasma in Silithus, 12 Einheiten gefrorenes Ektoplasma in Winterquell und 12 Einheiten stabiles Ektoplasma in den Östlichen Pestländern zu erhalten. Bringt das Ektoplasma dann mitsamt des Ektoplasmadestillierers zu Mux Manamix in Gadgetzan zurück." },
    [8925] = { "Eine portable Energiequelle", "Findet Magmafürst Bokk in der Brennenden Steppe, nehmt seinen Magmakern an Euch und bringt ihn zu Mux Manamix in Gadgetzan." },
    [8926] = { "Die angemessene Entlohnung", "Bringt Deliana in Eisenschmiede einen Gürtel des Wildherzens und ein Paar Handschuhe des Wildherzens." },
    [8927] = { "Die angemessene Entlohnung", "Bringt Mokvar in Orgrimmar einen Gürtel des Wildherzens und ein Paar Handschuhe des Wildherzens." },
    [8928] = { "Ein verschlagener Händler", "Sucht den Wichtel in der Höhle in der Nähe der Flüsternden Schlucht im Süden von Winterquell. Kauft ihm einen teufelselementaren Brennstab ab und kehrt zu Mux Manamix in Gadgetzan zurück." },
    [8929] = { "Suche nach Anthion", "Benutzt den extradimensionalen Geisterdetektor am Eingang zu Stratholme und sprecht mit dem Geist von Anthion Harmon." },
    [8930] = { "Suche nach Anthion", "Benutzt den extradimensionalen Geisterdetektor am Eingang zu Stratholme und sprecht mit dem Geist von Anthion Harmon." },
    [8931] = { "Die angemessene Entlohnung", "Bringt Deliana in Eisenschmiede einen Bestienjägergürtel und ein Paar Bestienjägerhandschuhe." },
    [8932] = { "Die angemessene Entlohnung", "Bringt Deliana in Eisenschmiede einen Gürtel des Magisters und ein Paar Handschuhe des Magisters." },
    [8933] = { "Die angemessene Entlohnung", "Bringt Deliana in Eisenschmiede einen Gürtel des Lichts und ein Paar Stulpen des Lichts." },
    [8934] = { "Die angemessene Entlohnung", "Bringt Deliana in Eisenschmiede einen Gürtel des Gläubigen und ein Paar Handschuhe des Gläubigen." },
    [8935] = { "Die angemessene Entlohnung", "Bringt Deliana in Eisenschmiede einen Gürtel der Schattenkunst und ein Paar Handschuhe der Schattenkunst." },
    [8936] = { "Die angemessene Entlohnung", "Bringt Deliana in Eisenschmiede einen Gürtel der Furcht und ein Paar Wickeltücher der Furcht." },
    [8937] = { "Die angemessene Entlohnung", "Bringt Deliana in Eisenschmiede einen Gürtel der Ehre und ein Paar Stulpen der Ehre." },
    [8938] = { "Die angemessene Entlohnung", "Bringt Mokvar in Orgrimmar einen Bestienjägergürtel und ein Paar Bestienjägerhandschuhe." },
    [8939] = { "Die angemessene Entlohnung", "Bringt Mokvar in Orgrimmar einen Gürtel des Magisters und ein Paar Handschuhe des Magisters." },
    [8940] = { "Die angemessene Entlohnung", "Bringt Mokvar in Orgrimmar einen Gürtel des Gläubigen und ein Paar Handschuhe des Gläubigen." },
    [8941] = { "Die angemessene Entlohnung", "Bringt Mokvar in Orgrimmar einen Gürtel der Schattenkunst und ein Paar Handschuhe der Schattenkunst." },
